'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import {
  Mail, Phone, MessageCircle, MoreHorizontal,
  Eye, PencilLine, StickyNote, Archive, ArchiveRestore, Loader2
} from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Skeleton } from '@/components/ui/skeleton'
import { Badge } from '@/components/ui/badge'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { type ClientTag } from './TagChip'
import { ClientTagEditor } from './ClientTagEditor'
import { HealthAlertBadge } from './HealthAlertBadge'
import { formatCurrency, formatRelativeTime, cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'

type Client = Database['public']['Tables']['clients']['Row']

const CONTACT_ICON: Record<string, React.ComponentType<{ className?: string }>> = {
  email: Mail,
  sms: Phone,
  phone: Phone,
  whatsapp: MessageCircle,
}

function ContactIcon({ method, value }: { method: string | null; value: string | null | undefined }) {
  if (!method || !value) return null
  const Icon = CONTACT_ICON[method] ?? Mail
  return (
    <Tooltip>
      <TooltipTrigger render={<span><Icon className="h-3.5 w-3.5 text-muted-foreground" /></span>} />
      <TooltipContent>{value}</TooltipContent>
    </Tooltip>
  )
}

function ClientRow({
  client,
  tagLibrary,
  healthSummary,
  isSelected,
  visibleKeys,
  onSelect,
  onEdit,
  onAddNote,
}: {
  client: Client
  tagLibrary: ClientTag[]
  healthSummary?: ClientHealthSummaryRow | null
  isSelected: boolean
  visibleKeys: Set<string>
  onSelect: (id: string, checked: boolean) => void
  onEdit: (client: Client) => void
  onAddNote: (clientId: string) => void
}) {
  const router = useRouter()
  const [isArchiving, setIsArchiving] = useState(false)

  const lastVisit = client.last_visit_at
    ? formatRelativeTime(new Date(client.last_visit_at))
    : 'Never'

  // Never-visited clients (last_visit_at null) are NEW, not inactive. Only
  // flag rows where we have a real visit timestamp older than 90 days.
  const daysSinceVisit = client.last_visit_at
    ? (Date.now() - new Date(client.last_visit_at).getTime()) / (1000 * 60 * 60 * 24)
    : null
  const isInactive = daysSinceVisit !== null && daysSinceVisit > 90

  const isArchived = Boolean(client.archived_at)
  const isBanned = client.is_banned

  async function handleArchive(e: React.MouseEvent) {
    e.stopPropagation()
    setIsArchiving(true)
    try {
      const res = await fetch(`/api/clients/${client.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to archive')
      toast.success('Client archived', {
        action: {
          label: 'Undo',
          onClick: async () => {
            const restoreRes = await fetch(`/api/clients/${client.id}/restore`, { method: 'POST' })
            if (restoreRes.ok) {
              toast.success('Client restored')
              router.refresh()
            } else {
              toast.error('Failed to restore client')
            }
          },
        },
      })
      router.refresh()
    } catch {
      toast.error('Failed to archive client')
    } finally {
      setIsArchiving(false)
    }
  }

  async function handleRestore(e: React.MouseEvent) {
    e.stopPropagation()
    setIsArchiving(true)
    try {
      const res = await fetch(`/api/clients/${client.id}/restore`, { method: 'POST' })
      if (!res.ok) throw new Error('Failed to restore')
      toast.success('Client restored')
      router.refresh()
    } catch {
      toast.error('Failed to restore client')
    } finally {
      setIsArchiving(false)
    }
  }

  const firstName = client.first_name
  const lastName = client.last_name ?? ''
  const initials = `${firstName[0] ?? '?'}${lastName[0] ?? ''}`.toUpperCase()

  return (
    <tr
      className={cn(
        'group border-b border-border/30 hover:bg-muted/20 transition-colors cursor-pointer hover-tint',
        isInactive && 'client-row-inactive',
        isArchived && 'client-row-archived',
        isBanned && 'opacity-70'
      )}
      style={{ viewTransitionName: `client-row-${client.id}` }}
      onClick={() => {
        if ('startViewTransition' in document) {
          document.startViewTransition(() => { router.push(`/clients/${client.id}`) })
        } else {
          router.push(`/clients/${client.id}`)
        }
      }}
    >
      {/* Checkbox */}
      <td className="w-10 pl-4 py-3" onClick={(e) => e.stopPropagation()}>
        <Checkbox
          checked={isSelected}
          onCheckedChange={(v) => onSelect(client.id, Boolean(v))}
          aria-label={`Select ${firstName} ${lastName}`}
        />
      </td>

      {/* Health alert dot — leftmost data column */}
      <td className="w-8 py-3 pl-1 pr-2" onClick={(e) => e.stopPropagation()}>
        <HealthAlertBadge
          summary={healthSummary ?? null}
          variant="dot"
          clientId={client.id}
        />
      </td>

      {/* Client name + phone */}
      <td className="py-3 pr-4">
        <div className="flex items-center gap-3">
          <div className={cn(
            'client-avatar-hero h-8 w-8 rounded-full flex items-center justify-center text-white text-xs font-semibold shrink-0 tabular-nums',
            isBanned && 'grayscale opacity-60'
          )}>
            {initials}
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-1.5">
              <p className="client-name text-sm font-medium truncate">
                {firstName} {lastName}
              </p>
              {isBanned && (
                <Badge variant="outline" className="text-destructive border-destructive/40 text-[10px] px-1 py-0 shrink-0">
                  Banned
                </Badge>
              )}
            </div>
            {client.phone && (
              <p className="text-xs text-muted-foreground tabular-nums">{client.phone}</p>
            )}
          </div>
        </div>
      </td>

      {/* Tags — inline editor opens on `+` trigger, doesn't steal row click */}
      {visibleKeys.has('tags') && (
        <td className="py-3 pr-4 w-48" onClick={(e) => e.stopPropagation()}>
          <ClientTagEditor
            clientId={client.id}
            clientTags={client.tags ?? []}
            tagLibrary={tagLibrary}
          />
        </td>
      )}

      {/* Last visit */}
      {visibleKeys.has('last_visit') && (
        <td className={cn('py-3 pr-4 w-28 text-sm tabular-nums', isInactive && 'text-destructive')}>
          {lastVisit}
        </td>
      )}

      {/* Total spent */}
      {visibleKeys.has('spent') && (
        <td className="py-3 pr-4 w-24 text-sm font-medium tabular-nums text-right">
          {formatCurrency(client.total_spent_cents)}
        </td>
      )}

      {/* Sessions */}
      {visibleKeys.has('sessions') && (
        <td className="py-3 pr-4 w-16 text-sm tabular-nums text-center">
          {client.total_sessions}
        </td>
      )}

      {/* Source */}
      {visibleKeys.has('source') && (
        <td className="py-3 pr-4 w-24 text-xs text-muted-foreground hidden lg:table-cell">
          {formatSource(client.source)}
        </td>
      )}

      {/* Contact method */}
      {visibleKeys.has('contact') && (
        <td className="py-3 pr-4 w-16" onClick={(e) => e.stopPropagation()}>
          <ContactIcon
            method={client.preferred_contact ?? 'email'}
            value={client.email ?? client.phone ?? undefined}
          />
        </td>
      )}

      {/* Actions — Edit + Add note as hover icons, rare actions in dropdown */}
      <td className="py-3 pr-3 w-[108px]" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-end gap-0.5">
          <Tooltip>
            <TooltipTrigger render={
              <Button
                variant="ghost"
                size="icon"
                className="h-7 w-7 opacity-0 group-hover:opacity-100 focus-visible:opacity-100 transition-opacity"
                onClick={(e) => { e.stopPropagation(); onEdit(client) }}
                aria-label="Edit client"
              >
                <PencilLine className="h-3.5 w-3.5" aria-hidden="true" />
              </Button>
            } />
            <TooltipContent>Edit</TooltipContent>
          </Tooltip>
          <Tooltip>

export const CLIENT_LIST_PAGE_SIZE = 50

export const CLIENT_LIST_SORT_KEYS = [
  'last_visit_desc',
  'last_visit_asc',
  'name_asc',
  'name_desc',
  'spent_desc',
  'sessions_desc',
] as const

export type ClientListSort = (typeof CLIENT_LIST_SORT_KEYS)[number]

export function isClientListSort(value: string): value is ClientListSort {
  return (CLIENT_LIST_SORT_KEYS as readonly string[]).includes(value)
}

export const CLIENT_LIST_SPENDING_TIERS = [
  '0-500',
  '500-2000',
  '2000-5000',
  '5000+',
] as const

export type ClientListSpendingTier = (typeof CLIENT_LIST_SPENDING_TIERS)[number]

export function isClientListSpendingTier(
  value: string,
): value is ClientListSpendingTier {
  return (CLIENT_LIST_SPENDING_TIERS as readonly string[]).includes(value)
}

export const CLIENT_LIST_LAST_VISIT_RANGES = [
  '30d',
  '90d',
  '90d+',
  'never',
] as const

export type ClientListLastVisitRange = (typeof CLIENT_LIST_LAST_VISIT_RANGES)[number]

export function isClientListLastVisitRange(
  value: string,
): value is ClientListLastVisitRange {
  return (CLIENT_LIST_LAST_VISIT_RANGES as readonly string[]).includes(value)
}

export interface ClientListFiltersContract {
  q: string
  tags: string[]
  vip: boolean
  inactive: boolean
  noShows: boolean
  showArchived: boolean
  hasAlerts: boolean
  spendingTier: '' | ClientListSpendingTier
  artistIds: string[]
  serviceIds: string[]
  lastVisitRange: '' | ClientListLastVisitRange
}

export interface ClientListRequestContract {
  filters: ClientListFiltersContract
  page?: number
  perPage?: number
  sort?: ClientListSort
}

export const CLIENT_LIST_SELECT = [
  'id',
  'studio_id',
  'first_name',
  'last_name',
  'email',
  'phone',
  'tags',
  'total_spent_cents',
  'total_sessions',
  'last_visit_at',
  'no_show_count',
  'source',
  'preferred_contact',
  'archived_at',
  'created_at',
  'updated_at',
  'date_of_birth',
  'address',
  'notes',
  'referral_source',
  'cancellation_count',
  'loyalty_points',
  'lifetime_value_cents',
  'avg_session_value_cents',
  'consent_minor',
  'instagram_handle',
  'tiktok_handle',
  'website_url',
  'is_banned',
  'banned_reason',
  'banned_at',
  'banned_by',
  'pronouns',
  'avatar_url',
].join(', ')

export function buildClientListSearchParams({
  filters,
  page = 1,
  perPage = CLIENT_LIST_PAGE_SIZE,
  sort = 'last_visit_desc',
}: ClientListRequestContract): URLSearchParams {
  const params = new URLSearchParams()

  if (filters.q) params.set('q', filters.q)
  if (filters.tags.length) params.set('tags', filters.tags.join(','))
  if (filters.vip) params.set('vip', 'true')
  if (filters.inactive) params.set('inactive', 'true')
  if (filters.noShows) params.set('no_show', 'true')
  params.set('archived', filters.showArchived ? 'any' : 'false')
  if (filters.hasAlerts) params.set('has_alerts', 'true')
  if (filters.spendingTier) params.set('spending', filters.spendingTier)
  if (filters.artistIds.length) params.set('artist_ids', filters.artistIds.join(','))
  if (filters.serviceIds.length) params.set('service_ids', filters.serviceIds.join(','))
  if (filters.lastVisitRange) params.set('last_visit_range', filters.lastVisitRange)
  params.set('sort', sort)
  params.set('page', String(page))
  params.set('per_page', String(perPage))

  return params
}

export interface ClientListSortOrder {
  column: string
  ascending: boolean
  nullsFirst?: boolean
}

export function getClientListSortOrders(sort: ClientListSort): ClientListSortOrder[] {
  switch (sort) {
    case 'last_visit_asc':
      return [{ column: 'last_visit_at', ascending: true, nullsFirst: false }]
    case 'name_asc':
      return [
        { column: 'first_name', ascending: true },
        { column: 'last_name', ascending: true },
      ]
    case 'name_desc':
      return [
        { column: 'first_name', ascending: false },
        { column: 'last_name', ascending: false },
      ]
    case 'spent_desc':
      return [{ column: 'total_spent_cents', ascending: false, nullsFirst: false }]
    case 'sessions_desc':
      return [{ column: 'total_sessions', ascending: false, nullsFirst: false }]
    case 'last_visit_desc':
    default:
      return [{ column: 'last_visit_at', ascending: false, nullsFirst: false }]
  }
}

export interface ClientListSpendingBounds {
  minInclusive?: number
  minExclusive?: number
  maxInclusive?: number
}

export function getClientListSpendingBounds(
  tier: ClientListSpendingTier,
): ClientListSpendingBounds {
  switch (tier) {
    case '0-500':
      return { minInclusive: 0, maxInclusive: 50_000 }
    case '500-2000':
      return { minExclusive: 50_000, maxInclusive: 200_000 }
    case '2000-5000':
      return { minExclusive: 200_000, maxInclusive: 500_000 }
    case '5000+':
      return { minInclusive: 500_000 }
  }
}

export type ClientListLastVisitConstraint =
  | { kind: 'between'; from: string; to: string }
  | { kind: 'before'; before: string }
  | { kind: 'null' }

function toISODate(date: Date): string {
  return date.toISOString().slice(0, 10)
}

export function getClientListLastVisitConstraint(
  range: ClientListLastVisitRange | '7d' | 'all',
): ClientListLastVisitConstraint | null {
  const now = new Date()

  switch (range) {
    case '7d': {
      const from = new Date(now)
      from.setDate(from.getDate() - 7)
      return { kind: 'between', from: toISODate(from), to: toISODate(now) }
    }
    case '30d': {
      const from = new Date(now)
      from.setDate(from.getDate() - 30)
      return { kind: 'between', from: toISODate(from), to: toISODate(now) }
    }
    case '90d': {
      const from = new Date(now)
      from.setDate(from.getDate() - 90)
      return { kind: 'between', from: toISODate(from), to: toISODate(now) }
    }
    case '90d+': {
      const before = new Date(now)
      before.setDate(before.getDate() - 90)
      return { kind: 'before', before: toISODate(before) }
    }
    case 'never':
      return { kind: 'null' }
    case 'all':
    default:
      return null
  }
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Loader2 } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { TagChip, type ClientTag } from './TagChip'

const NO_CHANGE = '__no_change__'

const SOURCE_OPTIONS = [
  { value: NO_CHANGE, label: 'Leave unchanged' },
  { value: 'public_booking', label: 'Booking page' },
  { value: 'walk_in', label: 'Walk-in' },
  { value: 'referral', label: 'Referral' },
  { value: 'social_media', label: 'Social media' },
  { value: 'manual', label: 'Manual entry' },
] as const

const CONTACT_OPTIONS = [
  { value: NO_CHANGE, label: 'Leave unchanged' },
  { value: 'email', label: 'Email' },
  { value: 'sms', label: 'SMS' },
  { value: 'phone', label: 'Phone' },
  { value: 'whatsapp', label: 'WhatsApp' },
] as const

type Source = Exclude<(typeof SOURCE_OPTIONS)[number]['value'], typeof NO_CHANGE>
type Contact = Exclude<(typeof CONTACT_OPTIONS)[number]['value'], typeof NO_CHANGE>

interface BulkEditDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  selectedIds: string[]
  tagLibrary: ClientTag[]
  onApplied: () => void
}

/**
 * Multi-client editor. Lets the operator change source / preferred contact
 * and add/remove tags on a selected batch in a single submit. Destructive-
 * by-omission fields (notes, DOB, email) deliberately excluded.
 */
export function BulkEditDialog({
  open,
  onOpenChange,
  selectedIds,
  tagLibrary,
  onApplied,
}: BulkEditDialogProps) {
  const [source, setSource] = useState<Source | typeof NO_CHANGE>(NO_CHANGE)
  const [contact, setContact] = useState<Contact | typeof NO_CHANGE>(NO_CHANGE)
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [submitting, setSubmitting] = useState(false)

  function reset() {
    setSource(NO_CHANGE)
    setContact(NO_CHANGE)
    setAddTagIds([])
    setRemoveTagIds([])
  }

  function handleOpenChange(next: boolean) {
    if (!next) reset()
    onOpenChange(next)
  }

  function toggleAddTag(id: string) {
    setAddTagIds((prev) => (prev.includes(id) ? prev.filter((t) => t !== id) : [...prev, id]))
    // Mutually exclusive — don't add + remove the same tag in one submit
    setRemoveTagIds((prev) => prev.filter((t) => t !== id))
  }

  function toggleRemoveTag(id: string) {
    setRemoveTagIds((prev) => (prev.includes(id) ? prev.filter((t) => t !== id) : [...prev, id]))
    setAddTagIds((prev) => prev.filter((t) => t !== id))
  }

  const addNames = tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.name)
  const removeNames = tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.name)

  const hasChanges =
    source !== NO_CHANGE ||
    contact !== NO_CHANGE ||
    addNames.length > 0 ||
    removeNames.length > 0

  async function handleSubmit() {
    if (!hasChanges) return
    setSubmitting(true)
    try {
      const payload: {
        client_ids: string[]
        source?: Source
        preferred_contact?: Contact
        tags_to_add: string[]
        tags_to_remove: string[]
      } = {
        client_ids: selectedIds,
        tags_to_add: addNames,
        tags_to_remove: removeNames,
      }
      if (source !== NO_CHANGE) payload.source = source
      if (contact !== NO_CHANGE) payload.preferred_contact = contact

      const res = await fetch('/api/clients/bulk-edit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to apply changes')
      }

      const count = selectedIds.length
      toast.success(`Updated ${count} client${count === 1 ? '' : 's'}`)
      onApplied()
      handleOpenChange(false)
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to apply changes'
      toast.error(msg)
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent
        showCloseButton={false}
        className="sm:max-w-md max-h-[85vh] flex flex-col gap-0 p-0 overflow-hidden"
      >
        <DialogHeader className="shrink-0 border-b border-border/60 px-6 py-4">
          <DialogTitle className="font-display text-[20px] leading-tight">
            Edit {selectedIds.length} client{selectedIds.length === 1 ? '' : 's'}
          </DialogTitle>
          <DialogDescription className="text-xs text-muted-foreground">
            Fields you leave unchanged won&rsquo;t be touched on any of the selected clients.
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          <div className="space-y-1.5">
            <Label htmlFor="bulk-edit-source" className="text-sm font-medium">Source</Label>
            <Select value={source} onValueChange={(v) => setSource(v as Source | typeof NO_CHANGE)}>
              <SelectTrigger id="bulk-edit-source">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {SOURCE_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="bulk-edit-contact" className="text-sm font-medium">Preferred contact</Label>
            <Select value={contact} onValueChange={(v) => setContact(v as Contact | typeof NO_CHANGE)}>
              <SelectTrigger id="bulk-edit-contact">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CONTACT_OPTIONS.map((opt) => (
                  <SelectItem key={opt.value} value={opt.value}>
                    {opt.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {tagLibrary.length > 0 && (
            <>
              <div className="space-y-2">
                <Label className="text-sm font-medium">Add tags</Label>
                <div className="flex flex-wrap gap-1.5">
                  {tagLibrary.map((tag) => {
                    const checked = addTagIds.includes(tag.id)
                    return (
                      <button
                        key={`add-${tag.id}`}
                        type="button"
                        onClick={() => toggleAddTag(tag.id)}
                        className="inline-flex items-center gap-1.5 rounded-md border border-border/60 bg-muted/40 px-2 py-1 text-xs hover:bg-muted transition-colors"
                      >
                        <Checkbox checked={checked} className="pointer-events-none" aria-hidden />
                        <TagChip tag={tag} size="xs" />
                      </button>
                    )
                  })}
                </div>
              </div>

              <div className="space-y-2">
                <Label className="text-sm font-medium">Remove tags</Label>
                <div className="flex flex-wrap gap-1.5">
                  {tagLibrary.map((tag) => {
                    const checked = removeTagIds.includes(tag.id)
                    return (
                      <button
                        key={`remove-${tag.id}`}
                        type="button"
                        onClick={() => toggleRemoveTag(tag.id)}
                        className="inline-flex items-center gap-1.5 rounded-md border border-border/60 bg-muted/40 px-2 py-1 text-xs hover:bg-muted transition-colors"
                      >
                        <Checkbox checked={checked} className="pointer-events-none" aria-hidden />
                        <TagChip tag={tag} size="xs" />
                      </button>
                    )
                  })}
                </div>
              </div>
            </>
          )}

          {tagLibrary.length === 0 && (
            <p className="text-xs text-muted-foreground">
              No tags yet. Create tags in Settings &rsaquo; Client tags to use them here.
            </p>
          )}
        </div>

        <div className="shrink-0 border-t border-border px-6 py-4 flex gap-3">
          <Button
            variant="outline"
            onClick={() => handleOpenChange(false)}
            disabled={submitting}
            className="h-10 flex-1"
          >
            Cancel
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={submitting || !hasChanges}
            className="h-10 flex-1"
          >
            {submitting && <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" aria-hidden="true" />}
            {submitting ? 'Applying…' : 'Apply'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

