'use client'

import { useState } from 'react'
import { Pin, MoreHorizontal, Trash2, Pencil } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import type { Database } from '@/lib/supabase/types'

type ClientNote = Database['public']['Tables']['client_notes']['Row'] & {
  profiles?: { full_name: string | null } | null
}

type NoteCategory = Database['public']['Tables']['client_notes']['Row']['category']

const CATEGORY_LABELS: Record<NoteCategory, string> = {
  general: 'General',
  medical: 'Medical',
  allergies: 'Allergies',
  skin: 'Skin type',
  emergency_contact: 'Emergency contact',
  aftercare: 'Aftercare',
  preferences: 'Preferences',
  artist_notes: 'Artist notes',
}

interface NoteCardProps {
  note: ClientNote
  onPinToggle: (noteId: string, pinned: boolean) => Promise<void>
  onDelete: (noteId: string) => void
}

export function NoteCard({ note, onPinToggle, onDelete }: NoteCardProps) {
  const [isPinning, setIsPinning] = useState(false)

  async function handlePinToggle() {
    setIsPinning(true)
    try {
      await onPinToggle(note.id, !note.is_pinned)
      toast.success(note.is_pinned ? 'Note unpinned' : 'Note pinned')
    } catch {
      toast.error('Failed to update pin')
    } finally {
      setIsPinning(false)
    }
  }

  const authorName = note.profiles?.full_name ?? 'Unknown'
  const formattedDate = new Date(note.created_at).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  })

  return (
    <div
      className={cn(
        'card bg-card border border-border/40 rounded-lg shadow-card',
        note.is_pinned && 'border-l-2 border-l-primary/40'
      )}
    >
      <div className="flex items-center gap-2 px-4 pt-3.5 pb-2">
        <span className={cn('h-2 w-2 rounded-full shrink-0', `note-dot-${note.category}`)} />
        <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground flex-1">
          {CATEGORY_LABELS[note.category]}
        </span>
        <Button
          variant="ghost"
          size="icon"
          className="h-7 w-7"
          onClick={handlePinToggle}
          disabled={isPinning}
          aria-label={note.is_pinned ? 'Unpin note' : 'Pin note'}
        >
          <Pin
            className={cn(
              'h-3.5 w-3.5 transition-colors',
              note.is_pinned ? 'fill-primary text-primary' : 'text-muted-foreground'
            )}
          />
        </Button>
        <DropdownMenu>
          <DropdownMenuTrigger render={
            <Button variant="ghost" size="icon" className="h-7 w-7">
              <MoreHorizontal className="h-3.5 w-3.5" />
              <span className="sr-only">More actions</span>
            </Button>
          } />
          <DropdownMenuContent align="end">
            <DropdownMenuItem>
              <Pencil className="mr-2 h-3.5 w-3.5" />
              Edit
            </DropdownMenuItem>
            <DropdownMenuItem
              className="text-destructive focus:text-destructive"
              onClick={() => onDelete(note.id)}
            >
              <Trash2 className="mr-2 h-3.5 w-3.5" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <p className="text-sm text-foreground px-4 pb-3 leading-relaxed">{note.body}</p>

      <p className="text-[11px] text-muted-foreground px-4 pb-3.5">
        {authorName} · {formattedDate}
      </p>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import { Page } from '@/components/shared/Page'
import { ClientsPageClient } from './ClientsPageClient'
import type { ClientTag } from '@/components/clients/TagChip'
import { CLIENT_LIST_PAGE_SIZE, CLIENT_LIST_SELECT } from '@/lib/clients/list-query'

export const metadata: Metadata = {
  title: 'Clients — InkOS',
}

export default async function ClientsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // S23 audit v1 — Clients page is the client list only. Tags moved to
  // /settings/tags, Consent Forms live in the sidebar, AI Design lives on
  // the individual client profile (or /ai-design).
  //
  // C2 addition — also fetch the total active-client count so the client
  // component can distinguish an EMPTY studio ("Add your first client")
  // from a FILTERED-ZERO studio ("No matches — clear filters").
  const [clientsResult, tagsResult, totalActiveResult] = await Promise.all([
    supabase
      .from('clients')
      .select(CLIENT_LIST_SELECT)
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(CLIENT_LIST_PAGE_SIZE),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
    supabase
      .from('clients')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', auth.studioId)
      .is('archived_at', null),
  ])
  const initialClients = (clientsResult.data ?? []) as unknown as Database['public']['Tables']['clients']['Row'][]
  const tagLibrary = (tagsResult.data ?? []) as ClientTag[]
  const totalActiveClients = totalActiveResult.count ?? 0

  return (
    <Page title="Clients">
      {/*
        The "+ New client" primary CTA lives inside ClientsPageClient because it
        opens a state-owned drawer. When we migrate to the ContextualSaveBar +
        shared drawer-provider pattern in Phase 2, lift it into `primaryAction`.
      */}
      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
        <ClientsPageClient
          initialClients={initialClients}
          tagLibrary={tagLibrary}
          totalActiveClients={totalActiveClients}
        />
      </Suspense>
    </Page>
  )
}

