    }
    toast.success('View deleted')
  } catch {
    toast.error('Failed to delete view')
  }
}

async function handleDuplicateView(view: ClientView) {
  try {
    const res = await fetch('/api/client-views', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: `${view.name} (copy)`,
        filters: view.filters,
        scope: 'private',
      }),
    })
    if (!res.ok) throw new Error('Failed to duplicate view')
    const json = await res.json() as { data: ClientView }
    setViews((prev) => [...prev, json.data])
    toast.success('View duplicated')
  } catch {
    toast.error('Failed to duplicate view')
  }
}

async function handleSetDefaultView(view: ClientView) {
  try {
    const res = await fetch(`/api/client-views/${view.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ is_default: true }),
    })
    if (!res.ok) throw new Error('Failed to set default')
    setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
    toast.success(`"${view.name}" is now your default view`)
  } catch {
    toast.error('Failed to set default view')
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const CreateTagSchema = z.object({
  name: z.string().min(1).max(50),
  color: z.enum(['purple', 'blue', 'emerald', 'amber', 'red', 'pink', 'cyan', 'gray']),
  icon: z.string().max(50).optional().nullable(),
  description: z.string().max(200).optional().nullable(),
})

export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('client_tags')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .order('name', { ascending: true })

    if (error) {
      logger.error({ err: error }, 'client tags GET failed')
      return NextResponse.json({ error: 'Failed to fetch tags' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'client-tags GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateTagSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  try {
    const supabase = await createClient()

    // Check duplicate by name (case-insensitive per unique index on lower(name))
    const { data: existing } = await supabase
      .from('client_tags')
      .select('id')
      .eq('studio_id', authUser.studioId)
      .ilike('name', parsed.data.name)
      .limit(1)
      .single()

    if (existing) {
      return NextResponse.json({ error: 'A tag with this name already exists.' }, { status: 409 })
    }

    type TagInsert = {
      studio_id: string
      name: string
      color: string
      icon?: string | null
      description?: string | null
    }
    const tagInsert: TagInsert = {
      studio_id: authUser.studioId,
      name: parsed.data.name,
      color: parsed.data.color,
    }
    if (parsed.data.icon !== undefined) tagInsert.icon = parsed.data.icon ?? null
    if (parsed.data.description !== undefined) tagInsert.description = parsed.data.description ?? null

    const { data, error } = await supabase
      .from('client_tags')
      .insert(tagInsert)
      .select()
      .single()

    if (error) {
      if (error.code === '23505') {
        return NextResponse.json({ error: 'A tag with this name already exists.' }, { status: 409 })
      }
      logger.error({ err: error }, 'tag create failed')
      return NextResponse.json({ error: 'Failed to create tag' }, { status: 500 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'client-tags POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

