955	   DARK MODE — single authoritative .dark block
956	   Philosophy: warm onyx at candlelight temperature — NEVER pitch-black void.
957	   Lifted 2% across the ladder (page L16, card L22, sidebar L13) so surfaces
958	   read as distinct tiles, not a single flat black. Hue 85 (warm stone) with
959	   mild chroma bump 0.012–0.018 for editorial warmth. Shadows carry less
960	   weight because the elevation ladder itself does the lifting.
961	────────────────────────────────────────────────────────── */
962	.dark {
963	  /* ── Core semantic ── */
964	  --color-background:          oklch(17% 0.013 85);
965	  --color-foreground:          oklch(95% 0.008 85);
966	  --color-card:                oklch(22% 0.015 85);
967	  --color-card-foreground:     oklch(95% 0.008 85);
968	  --color-popover:             oklch(24% 0.016 85);
969	  --color-popover-foreground:  oklch(95% 0.008 85);
970	
971	  /* Primary inverts: Bone button surface with Onyx text (premium B2B). */
972	  --color-primary:             oklch(94% 0.008 85);
973	  --color-primary-foreground:  oklch(16% 0.012 85);
974	
975	  --color-secondary:           oklch(26% 0.014 85);
976	  --color-secondary-foreground: oklch(90% 0.01 85);
977	
978	  --color-muted:               oklch(25% 0.014 85);
979	  --color-muted-foreground:    oklch(72% 0.013 85);   /* AA on body copy */
980	
981	  /* Accent — Rust tint (Brand Book §4.4 Rule 2: Rust is earned) */
982	  --color-accent:              oklch(24% 0.045 35);
983	  --color-accent-foreground:   oklch(74% 0.15 35);
984	
985	  --color-destructive:         oklch(62% 0.22 27);
986	  --color-destructive-foreground: oklch(99% 0 0);
987	
988	  /* Hairlines — lifted to L28 so they're visible on L22 cards */
989	  --color-border:              oklch(28% 0.013 85);
990	  --color-input:               oklch(24% 0.012 85);
991	  --color-ring:                oklch(58% 0.16 35);
992	
993	  /* ── Elevation ladder — widened deltas (5–6% per step) so cards pop ── */
994	  --color-page-bg:             oklch(16% 0.012 85);   /* was 14 */
995	  --color-header-bg:           oklch(14% 0.012 85);   /* recessed from page */
