import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { fetchClientHealthSummariesForIds } from '@/lib/clients/health'
import { logger } from '@/lib/logger'

// Comma-separated UUIDs, capped so a rogue caller can't request a 10k batch.
const UUID_REGEX = /^[0-9a-f-]{36}$/i
const QuerySchema = z.object({
  ids: z
    .string()
    .min(36)
    .max(50 * 37) // 50 UUIDs × (36 chars + comma)
    .transform((raw) => raw.split(',').filter(Boolean))
    .pipe(z.array(z.string().regex(UUID_REGEX)).min(1).max(50)),
})

/**
 * Batch-fetch health summaries for a list of client IDs.
 *
 * Used by the clients list page to render the red "has alert" dot on each
 * row without an N+1 query. Scoped to the authenticated user's studio via
 * RLS on the underlying `client_health_summary` view.
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = QuerySchema.safeParse({ ids: searchParams.get('ids') ?? '' })
  if (!parsed.success) {
    return NextResponse.json({ error: 'Invalid ids parameter' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const map = await fetchClientHealthSummariesForIds(
      supabase,
      parsed.data.ids,
      authUser.studioId,
    )

    // Serialize Map → plain object for JSON transport
    const summaries: Record<string, unknown> = {}
    for (const [id, row] of map.entries()) summaries[id] = row

    return NextResponse.json({ data: summaries })
  } catch (err) {
    logger.error({ err }, 'client health-summaries GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

