// Batch-fetch health summaries whenever the visible client set changes.
// Rendered as the red dot in the leftmost ClientsTable column — artists
// need to see allergies before clicking into a profile.
useEffect(() => {
  if (clients.length === 0) {
    setHealthSummaries(new Map())
    return
  }
  const missingIds = clients
    .map((c) => c.id)
    .filter((id) => !healthSummaries.has(id))
  if (missingIds.length === 0) return

  const controller = new AbortController()
  const ids = missingIds.join(',')
  void fetch(`/api/clients/health-summaries?ids=${encodeURIComponent(ids)}`, {
    signal: controller.signal,
  })
    .then((r) => (r.ok ? r.json() : null))
    .then((json: { data?: Record<string, ClientHealthSummaryRow> } | null) => {
      if (!json?.data) return
      setHealthSummaries((prev) => {
        const next = new Map(prev)
        for (const [id, row] of Object.entries(json.data ?? {})) next.set(id, row)
        return next
      })
    })
    .catch(() => {
      // Non-fatal — dots just won't render for these rows until next refresh.
    })
  return () => controller.abort()
}, [clients, healthSummaries])

