interface BulkActionsBarProps {
  selectedIds: string[]
  tagLibrary: ClientTag[]
  /**
   * When `archived`, the bar renders only actions that make sense on archived
   * rows (Restore + Clear). Edit / tag / export / archive are hidden because
   * they're either no-ops or noisy for archived records.
   */
  mode?: 'active' | 'archived'
  onClearSelection: () => void
  onArchived: () => void
  onTagsApplied: () => void
  onRestored?: () => void
}

export function BulkActionsBar({
  selectedIds,
  tagLibrary,
  mode = 'active',
  onClearSelection,
  onArchived,
  onTagsApplied,
  onRestored,
}: BulkActionsBarProps) {
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [isArchiving, setIsArchiving] = useState(false)
  const [isRestoring, setIsRestoring] = useState(false)
  const [isTagging, setIsTagging] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  const [editOpen, setEditOpen] = useState(false)

  async function handleRestore() {
    setIsRestoring(true)
    try {
      const results = await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}/restore`, { method: 'POST' }).then((r) => r.ok),
        ),
      )
      const ok = results.filter(Boolean).length
      if (ok === 0) throw new Error('Failed to restore clients')
      toast.success(
        `${ok} client${ok === 1 ? '' : 's'} restored${ok < selectedIds.length ? ` (${selectedIds.length - ok} failed)` : ''}`,
      )
      onClearSelection()
      onRestored?.()
    } catch {
      toast.error('Failed to restore clients')
    } finally {
      setIsRestoring(false)
    }
  }

