'use client'

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { Plus, Settings2, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { TagChip, resolveTagSlugs, type ClientTag } from './TagChip'

// Colors accepted by POST /api/client-tags. Rotated so successively created
// tags don't all land on the same color. No Rust — it's reserved for alerts.
const TAG_COLOR_ROTATION: ClientTag['color'][] = [
  'purple', 'blue', 'emerald', 'amber', 'pink', 'cyan', 'gray',
]
function pickTagColor(existingCount: number): ClientTag['color'] {
  return TAG_COLOR_ROTATION[existingCount % TAG_COLOR_ROTATION.length] ?? 'purple'
}

interface ClientTagEditorProps {
  clientId: string
  clientTags: string[]
  tagLibrary: ClientTag[]
  maxVisible?: number
  /**
   * Layout variant:
   *   `row` — compact inline display for the Clients table cell, `+` icon
   *   acts as the popover trigger without disturbing row click.
   *   `stacked` — wraps under a label, for profile page usage.
   */
  variant?: 'row' | 'stacked'
}

/**
 * Per-client tag editor. Shows resolved chips + a `+` trigger that opens a
 * searchable picker. Toggling a tag calls the existing bulk-tag endpoint
 * with `client_ids: [clientId]` so all writes go through one canonical
 * RPC (`bulk_tag_clients`) — no new server code.
 */
export function ClientTagEditor({
  clientId,
  clientTags,
  tagLibrary,
  maxVisible = 3,
  variant = 'row',
}: ClientTagEditorProps) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [pending, setPending] = useState(false)
  const [createQuery, setCreateQuery] = useState('')
  const [creating, setCreating] = useState(false)

  const resolved = resolveTagSlugs(clientTags, tagLibrary)
  const visibleTags = variant === 'stacked' ? resolved : resolved.slice(0, maxVisible)
  const overflow = variant === 'stacked' ? 0 : resolved.length - maxVisible

  async function toggle(tag: ClientTag) {
    const currentlyOn = clientTags.some(
      (t) => t.toLowerCase() === tag.name.toLowerCase() || t === tag.id,
    )
    setPending(true)
    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_ids: [clientId],
          tags_to_add: currentlyOn ? [] : [tag.name],
          tags_to_remove: currentlyOn ? [tag.name] : [],
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tag')
      }
      router.refresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update tag')
    } finally {
      setPending(false)
    }
  }

  async function createAndApply(nameRaw: string) {
    const name = nameRaw.trim()
    if (!name) return
    if (name.length > 50) {
      toast.error('Tag name must be 50 characters or fewer')
      return
    }
    // Prevent a duplicate POST — the server would 409 anyway, but we can
    // skip the round-trip and just toggle the existing tag on for this client.
    const existing = tagLibrary.find((t) => t.name.toLowerCase() === name.toLowerCase())
    if (existing) {
      setCreateQuery('')
      await toggle(existing)
      return
    }
    setCreating(true)
    try {
      const res = await fetch('/api/client-tags', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name,
          color: pickTagColor(tagLibrary.length),
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to create tag')
      }
      const json = await res.json() as { data: ClientTag }
      // Apply the new tag to this client immediately so the popover "acts"
      // instead of silently adding a tag to the library with no visible effect.
      await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_ids: [clientId],
          tags_to_add: [json.data.name],
          tags_to_remove: [],
        }),
      })
      toast.success(`Tag "${json.data.name}" created`)
      setCreateQuery('')
      router.refresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create tag')
    } finally {
      setCreating(false)
    }
  }

  const trimmedQuery = createQuery.trim()
  const queryMatchesExisting = trimmedQuery.length > 0
    && tagLibrary.some((t) => t.name.toLowerCase() === trimmedQuery.toLowerCase())

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <div
        className={
          variant === 'stacked'
            ? 'flex flex-wrap items-center gap-1.5'
            : 'flex flex-wrap items-center gap-1'
        }
      >
        {visibleTags.map((tag) => (
          <TagChip key={tag.id} tag={tag} size="sm" />
        ))}
        {overflow > 0 && (
          <span className="text-xs text-muted-foreground bg-muted rounded-full px-2 py-0.5 tabular-nums">
            +{overflow}
          </span>
        )}
        <PopoverTrigger
          render={
            <Button
              variant="ghost"
              size="icon"
              className={
                variant === 'stacked'
                  ? 'h-6 w-6 text-muted-foreground hover:text-foreground'
                  : 'h-5 w-5 opacity-0 group-hover:opacity-100 focus-visible:opacity-100 transition-opacity text-muted-foreground hover:text-foreground'
              }
              aria-label={resolved.length === 0 ? 'Add tags' : 'Edit tags'}
            >
              {pending ? <Loader2 className="h-3 w-3 animate-spin" aria-hidden="true" /> : <Plus className="h-3 w-3" aria-hidden="true" />}
            </Button>
          }
        />
      </div>

      <PopoverContent
        align="start"
        className="w-[260px] p-0"
        onClick={(e) => e.stopPropagation()}
      >
        {tagLibrary.length === 0 ? (
          // First-run: no tags yet. Offer inline creation so the user doesn't
          // bounce to /settings/tags and come back to a stale library.
          <div className="p-3 space-y-2">
            <p className="text-xs text-muted-foreground">No tags yet. Create one:</p>
            <form
              onSubmit={(e) => { e.preventDefault(); void createAndApply(createQuery) }}
              className="flex items-center gap-1.5"
            >
              <Input
                autoFocus
                value={createQuery}
                onChange={(e) => setCreateQuery(e.target.value)}
                placeholder="e.g. VIP, walk-in"
                maxLength={50}
                className="h-8 text-xs"
                disabled={creating}
              />
              <Button
                type="submit"
                size="sm"
                className="h-8 px-2 shrink-0"
                disabled={creating || trimmedQuery.length === 0}
                aria-label="Create tag"
              >
                {creating
                  ? <Loader2 className="h-3 w-3 animate-spin" aria-hidden="true" />
                  : <Plus className="h-3 w-3" aria-hidden="true" />}
              </Button>
            </form>
            <Button
              variant="ghost"
              size="sm"
              className="w-full h-7 text-xs gap-1 justify-start text-muted-foreground"
              render={<Link href="/settings/tags" />}
            >
              <Settings2 className="h-3 w-3" aria-hidden="true" />
              Manage tags
            </Button>
          </div>
        ) : (
          <Command>
            <CommandInput
              placeholder="Search or create…"
              value={createQuery}
              onValueChange={setCreateQuery}
              className="h-8"
            />
            <CommandList>
              <CommandEmpty>
                {trimmedQuery.length > 0 ? (
                  <button
                    type="button"
                    onClick={() => void createAndApply(trimmedQuery)}
                    disabled={creating}
                    className="w-full inline-flex items-center gap-1.5 px-2 py-1.5 text-xs text-foreground hover:bg-muted rounded-sm disabled:opacity-60"
                  >
                    {creating
                      ? <Loader2 className="h-3 w-3 animate-spin" aria-hidden="true" />
                      : <Plus className="h-3 w-3" aria-hidden="true" />}
                    Create &ldquo;{trimmedQuery}&rdquo;
                  </button>
                ) : (
                  <span className="text-xs text-muted-foreground px-2 py-1.5 block">No tags match</span>
                )}
              </CommandEmpty>
              <CommandGroup>
                {tagLibrary.map((tag) => {
                  const isOn = clientTags.some(
                    (t) => t.toLowerCase() === tag.name.toLowerCase() || t === tag.id,
                  )
                  return (
                    <CommandItem
                      key={tag.id}
                      value={tag.name}
                      onSelect={() => toggle(tag)}
                      className="flex items-center gap-2"
                    >
                      <Checkbox checked={isOn} className="pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  )
                })}
              </CommandGroup>
            </CommandList>
            {trimmedQuery.length > 0 && !queryMatchesExisting && (
              <div className="border-t border-border/40 p-1.5">
                <button
                  type="button"
                  onClick={() => void createAndApply(trimmedQuery)}
                  disabled={creating}
                  className="w-full inline-flex items-center gap-1.5 px-2 py-1.5 text-xs text-foreground hover:bg-muted rounded-sm disabled:opacity-60"
                >
                  {creating
                    ? <Loader2 className="h-3 w-3 animate-spin" aria-hidden="true" />
                    : <Plus className="h-3 w-3" aria-hidden="true" />}
                  Create &ldquo;{trimmedQuery}&rdquo;
                </button>
              </div>
            )}
            <div className="border-t border-border/40 p-1.5">
              <Button
                variant="ghost"
                size="sm"
                className="w-full h-7 text-xs gap-1 justify-start text-muted-foreground"
                render={<Link href="/settings/tags" />}
              >
                <Settings2 className="h-3 w-3" aria-hidden="true" />
                Manage tags
              </Button>
            </div>
          </Command>
        )}
      </PopoverContent>
    </Popover>
  )
}

'use client'

import { useState } from 'react'
import { X, Tag, XCircle, Download, Archive, ArchiveRestore, PencilLine, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { TagChip, type ClientTag } from './TagChip'
import { BulkEditDialog } from './BulkEditDialog'
import { cn } from '@/lib/utils'

interface BulkActionsBarProps {
  selectedIds: string[]
  tagLibrary: ClientTag[]
  /**
   * When `archived`, the bar renders only actions that make sense on archived
   * rows (Restore + Clear). Edit / tag / export / archive are hidden because
   * they're either no-ops or noisy for archived records.
   */
  mode?: 'active' | 'archived'
  onClearSelection: () => void
  onArchived: () => void
  onTagsApplied: () => void
  onRestored?: () => void
}

export function BulkActionsBar({
  selectedIds,
  tagLibrary,
  mode = 'active',
  onClearSelection,
  onArchived,
  onTagsApplied,
  onRestored,
}: BulkActionsBarProps) {
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [isArchiving, setIsArchiving] = useState(false)
  const [isRestoring, setIsRestoring] = useState(false)
  const [isTagging, setIsTagging] = useState(false)
  const [isExporting, setIsExporting] = useState(false)
  const [editOpen, setEditOpen] = useState(false)

  async function handleRestore() {
    setIsRestoring(true)
    try {
      const results = await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}/restore`, { method: 'POST' }).then((r) => r.ok),
        ),
      )
      const ok = results.filter(Boolean).length
      if (ok === 0) throw new Error('Failed to restore clients')
      toast.success(
        `${ok} client${ok === 1 ? '' : 's'} restored${ok < selectedIds.length ? ` (${selectedIds.length - ok} failed)` : ''}`,
      )
      onClearSelection()
      onRestored?.()
    } catch {
      toast.error('Failed to restore clients')
    } finally {
      setIsRestoring(false)
    }
  }

  async function handleApplyTags(action: 'add' | 'remove') {
    // Resolve canonical tag names — the RPC stores tag names on clients.tags
    // (JSON array of names, not IDs), so we must translate selected IDs back
    // to their canonical name strings before sending.
    const tagNames = action === 'add'
      ? tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.name)
      : tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.name)

    if (tagNames.length === 0) return
    setIsTagging(true)

    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_ids: selectedIds,
          tags_to_add: action === 'add' ? tagNames : [],
          tags_to_remove: action === 'remove' ? tagNames : [],
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tags')
      }
      toast.success(`Tags ${action === 'add' ? 'applied' : 'removed'}`)
      if (action === 'add') setAddTagIds([])
      else setRemoveTagIds([])
      onTagsApplied()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update tags'
      toast.error(message)
    } finally {
      setIsTagging(false)
    }
  }

  async function handleArchive() {
    setIsArchiving(true)
    try {
      await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}`, { method: 'DELETE' })
        )
      )
      toast.success(`${selectedIds.length} client${selectedIds.length !== 1 ? 's' : ''} archived`, {
        action: {
          label: 'Undo',
          onClick: async () => {
            await Promise.all(
              selectedIds.map((id) => fetch(`/api/clients/${id}/restore`, { method: 'POST' }))
            )
            toast.success('Restored')
            onArchived()
          },
        },
      })
      onClearSelection()
      onArchived()
    } catch {
      toast.error('Failed to archive clients')
    } finally {
      setIsArchiving(false)
    }
  }

  async function handleExport() {
    setIsExporting(true)
    const toastId = toast.loading('Preparing export…')
    try {
      const ids = selectedIds.join(',')
      const res = await fetch(`/api/clients/export?ids=${ids}`)
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `clients-${new Date().toISOString().slice(0, 10)}.csv`
      a.click()
      URL.revokeObjectURL(url)
      toast.success('Downloading', { id: toastId })
    } catch {
      toast.error('Export failed', { id: toastId })
    } finally {
      setIsExporting(false)
    }
  }

  if (selectedIds.length === 0) return null

  return (
    <div
      className={cn(
        'flex items-center justify-between gap-3 px-4 py-2.5',
        'bg-primary/[0.08] border border-primary/20 rounded-lg',
        'animate-in fade-in-0 slide-in-from-top-2 duration-150'
      )}
    >
      <div className="flex items-center gap-2">
        <span className="h-2 w-2 rounded-full bg-primary" />
        <span className="text-sm font-medium">
          {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''} selected
        </span>
      </div>

      <div className="flex items-center gap-1.5">
        {mode === 'archived' && (
          <Button
            variant="outline"
            size="sm"
            className="h-9 gap-1.5"
            onClick={handleRestore}
            disabled={isRestoring}
          >
            {isRestoring
              ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" />
              : <ArchiveRestore className="h-3.5 w-3.5" />}
            Restore
          </Button>
        )}

        {mode === 'active' && (
          <>
        {/* Bulk edit (source / preferred contact / tags) */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={() => setEditOpen(true)}
        >
          <PencilLine className="h-3.5 w-3.5" />
          Edit
        </Button>

        {/* Apply tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><Tag className="h-3.5 w-3.5" />Add tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setAddTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={addTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {addTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('add')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Apply tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Remove tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><XCircle className="h-3.5 w-3.5" />Remove tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setRemoveTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={removeTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {removeTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    variant="destructive"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('remove')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Remove tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Export */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={handleExport}
          disabled={isExporting}
        >
          {isExporting ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
          Export CSV
        </Button>

        {/* Archive */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="outline"
                size="sm"
                className="h-9 gap-1.5"
                loading={isArchiving}
                loadingLabel="Archiving..."
              >
                <Archive className="h-3.5 w-3.5" />
                Archive
              </Button>
            }
          />
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Archive {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''}?</AlertDialogTitle>
              <AlertDialogDescription>
                They will be hidden from your client list and won&apos;t appear in new bookings. You can restore them from the archived view.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleArchive}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                {isArchiving ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : 'Archive'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
          </>
        )}

        {/* Clear selection */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={onClearSelection}
          aria-label="Clear selection"
        >
          <X className="h-4 w-4" />
        </Button>
      </div>

      {mode === 'active' && (
        <BulkEditDialog
          open={editOpen}
          onOpenChange={setEditOpen}
          selectedIds={selectedIds}
          tagLibrary={tagLibrary}
          onApplied={onTagsApplied}
        />
      )}
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { Suspense } from 'react'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import { Page } from '@/components/shared/Page'
import { ClientsPageClient } from './ClientsPageClient'
import type { ClientTag } from '@/components/clients/TagChip'
import { CLIENT_LIST_PAGE_SIZE, CLIENT_LIST_SELECT } from '@/lib/clients/list-query'
import { fetchClientHealthSummariesForIds } from '@/lib/clients/health'
import type { ClientHealthSummaryRow } from '@/lib/clients/health-types'

export const metadata: Metadata = {
  title: 'Clients — InkOS',
}

export default async function ClientsPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // S23 audit v1 — Clients page is the client list only. Tags moved to
  // /settings/tags, Consent Forms live in the sidebar, AI Design lives on
  // the individual client profile (or /ai-design).
  //
  // C2 addition — also fetch the total active-client count so the client
  // component can distinguish an EMPTY studio ("Add your first client")
  // from a FILTERED-ZERO studio ("No matches — clear filters").
  const [clientsResult, tagsResult, totalActiveResult] = await Promise.all([
    supabase
      .from('clients')
      .select(CLIENT_LIST_SELECT)
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(CLIENT_LIST_PAGE_SIZE),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
    supabase
      .from('clients')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', auth.studioId)
      .is('archived_at', null),
  ])
  const initialClients = (clientsResult.data ?? []) as unknown as Database['public']['Tables']['clients']['Row'][]
  const tagLibrary = (tagsResult.data ?? []) as ClientTag[]
  const totalActiveClients = totalActiveResult.count ?? 0

  // Batch-fetch health summaries for the initial page so rows with pinned
  // allergies / medical notes render the red dot on first paint (no flash).
  const initialClientIds = initialClients.map((c) => c.id)
  const summariesMap = await fetchClientHealthSummariesForIds(
    supabase,
    initialClientIds,
    auth.studioId,
  )
  const initialHealthSummaries: Record<string, ClientHealthSummaryRow> = {}
  for (const [id, row] of summariesMap.entries()) {
    initialHealthSummaries[id] = row
  }

  return (
    <Page title="Clients">
      {/*
        The "+ New client" primary CTA lives inside ClientsPageClient because it
        opens a state-owned drawer. When we migrate to the ContextualSaveBar +
        shared drawer-provider pattern in Phase 2, lift it into `primaryAction`.
      */}
      <Suspense fallback={<div className="flex-1 animate-pulse bg-muted/20 m-6 rounded-xl" />}>
        <ClientsPageClient
          initialClients={initialClients}
          initialHealthSummaries={initialHealthSummaries}
          tagLibrary={tagLibrary}
          totalActiveClients={totalActiveClients}
        />
      </Suspense>
    </Page>
  )
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { fetchClientHealthSummariesForIds } from '@/lib/clients/health'
import { logger } from '@/lib/logger'

// Comma-separated UUIDs, capped so a rogue caller can't request a 10k batch.
const UUID_REGEX = /^[0-9a-f-]{36}$/i
const QuerySchema = z.object({
  ids: z
    .string()
    .min(36)
    .max(50 * 37) // 50 UUIDs × (36 chars + comma)
    .transform((raw) => raw.split(',').filter(Boolean))
    .pipe(z.array(z.string().regex(UUID_REGEX)).min(1).max(50)),
})

/**
 * Batch-fetch health summaries for a list of client IDs.
 *
 * Used by the clients list page to render the red "has alert" dot on each
 * row without an N+1 query. Scoped to the authenticated user's studio via
 * RLS on the underlying `client_health_summary` view.
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = QuerySchema.safeParse({ ids: searchParams.get('ids') ?? '' })
  if (!parsed.success) {
    return NextResponse.json({ error: 'Invalid ids parameter' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const map = await fetchClientHealthSummariesForIds(
      supabase,
      parsed.data.ids,
      authUser.studioId,
    )

    // Serialize Map → plain object for JSON transport
    const summaries: Record<string, unknown> = {}
    for (const [id, row] of map.entries()) summaries[id] = row

    return NextResponse.json({ data: summaries })
  } catch (err) {
    logger.error({ err }, 'client health-summaries GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

