'use client'

/**
 * MessagesShell — 3-pane omnichannel inbox shell.
 *
 * Desktop ≥1280px:  rail(72) | list(360) | thread(1fr) | context(380, toggleable)
 * Tablet 1024-1279: same grid but context renders as Sheet
 * Mobile <1024:     stacked — channel rail as horizontal strip, list or thread only
 *
 * All layout state lives here. Data is passed from the server page.
 */

import { useState, useCallback, useEffect } from 'react'
import { useMessagesShortcuts } from '@/hooks/messages/use-messages-shortcuts'
import { useIsMobile } from '@/hooks/useIsMobile'
import { ChannelRail } from './ChannelRail'
import { ConversationList } from './ConversationList'
import { ThreadPanel } from './ThreadPanel'
import { ContextPane } from './ContextPane'
import { MessagesHeader } from './MessagesHeader'
import { ShortcutCheatsheet } from './ShortcutCheatsheet'
import type {
  ConversationWithClient,
  ConversationMessage,
  ConversationContext,
  MessageTemplate,
  Channel,
} from '@/lib/messaging/queries'
import type { SmartReply } from '@/lib/messaging/triage'

// ─── Types ────────────────────────────────────────────────────────────────────

interface StudioMember {
  id: string
  user_id: string
  display_name?: string | null | undefined
  role: string
}

export interface MessagesShellProps {
  conversations: ConversationWithClient[]
  activeConversation: ConversationWithClient | null
  activeMessages: ConversationMessage[]
  conversationContext: ConversationContext | null
  templates: MessageTemplate[]
  unreadCounts: Record<Channel, number>
  studioId: string
  activeConversationId: string | null
  searchParams: { c?: string | undefined; channel?: string | undefined; filter?: string | undefined; q?: string | undefined }
  currentUserId: string
  currentUserName: string
  members: StudioMember[]
  smartReplies: SmartReply[]
}

// ─── useIsWide (≥1280px) ──────────────────────────────────────────────────────

function useIsWide(): boolean {
  const [isWide, setIsWide] = useState(false)

  useEffect(() => {
    function update() {
      setIsWide(window.innerWidth >= 1280)
    }
    update()
    const mql = window.matchMedia('(min-width: 1280px)')
    mql.addEventListener('change', update)
    return () => mql.removeEventListener('change', update)
  }, [])

  return isWide
}

function useIsTablet(): boolean {
  const [isTablet, setIsTablet] = useState(false)

  useEffect(() => {
    function update() {
      const w = window.innerWidth
      setIsTablet(w >= 1024 && w < 1280)
    }
    update()
    const mql = window.matchMedia('(min-width: 1024px) and (max-width: 1279px)')
    mql.addEventListener('change', update)
    return () => mql.removeEventListener('change', update)
  }, [])

  return isTablet
}

// ─── MessagesShell ─────────────────────────────────────────────────────────────

export function MessagesShell({
  conversations,
  activeConversation,
  activeMessages,
  conversationContext,
  templates,
  unreadCounts,
  studioId,
  activeConversationId,
  searchParams,
  currentUserId,
  currentUserName,
  members,
  smartReplies,
}: MessagesShellProps) {
  const isMobile = useIsMobile()
  const isWide = useIsWide()
  const isTablet = useIsTablet()

  const [showContext, setShowContext] = useState(false)
  const [showCheatsheet, setShowCheatsheet] = useState(false)

  const currentChannel = searchParams.channel ?? null

  // Keyboard shortcuts
  const handleToggleInternalNote = useCallback(() => {
    // Raise to composer via internalNoteMode — toggled at composer level via shortcut
    // For now: noop (composer handles its own state)
  }, [])

  useMessagesShortcuts({
    onFocusSearch: useCallback(() => {
      const el = document.querySelector<HTMLInputElement>('[aria-label="Search conversations"]')
      el?.focus()
    }, []),
    onNavigateDown: useCallback(() => {
      // Implemented in ConversationList via keyboard events
    }, []),
    onNavigateUp: useCallback(() => {
      // Implemented in ConversationList via keyboard events
    }, []),
    onFocusComposer: useCallback(() => {
      const el = document.querySelector<HTMLTextAreaElement>('[aria-label="Message body"]') ??
        document.querySelector<HTMLTextAreaElement>('[aria-label="Internal note body"]')
      el?.focus()
    }, []),
    onAssign: useCallback(() => void 0, []),
    onArchive: useCallback(() => void 0, []),
    onStar: useCallback(() => void 0, []),
    onToggleInternalNote: handleToggleInternalNote,
    onShowCheatsheet: useCallback(() => setShowCheatsheet(true), []),
    onClose: useCallback(() => setShowContext(false), []),
  })

  // ── Mobile layout ──────────────────────────────────────────────────────────
  if (isMobile) {
    if (activeConversation) {
      return (
        <div className="flex flex-col h-full">
          <MessagesHeader
            unreadCounts={unreadCounts}
            onShowCheatsheet={() => setShowCheatsheet(true)}
          />
          <div className="flex-1 min-h-0">
            <ThreadPanel
              conversation={activeConversation}
              initialMessages={activeMessages}
              conversationContext={conversationContext}
              templates={templates}
              initialSmartReplies={smartReplies}
              studioId={studioId}
              currentUserId={currentUserId}
              currentUserName={currentUserName}
              members={members}
              showContextPane={false}
              onToggleContext={() => setShowContext(true)}
              showBackButton
            />
          </div>
          {conversationContext && (
            <ContextPane
              context={conversationContext}
              conversationId={activeConversationId ?? ''}
              onClose={() => setShowContext(false)}
              renderAsSheet
              sheetOpen={showContext}
            />
          )}
          <ShortcutCheatsheet open={showCheatsheet} onClose={() => setShowCheatsheet(false)} />
        </div>
      )
    }

    return (
      <div className="flex flex-col h-full">
        <MessagesHeader
          unreadCounts={unreadCounts}
          onShowCheatsheet={() => setShowCheatsheet(true)}
        />
        {/* Horizontal channel strip */}
        <div className="flex overflow-x-auto border-b border-border bg-background shrink-0 px-2 py-1 gap-1">
          {(['all', 'sms', 'email', 'instagram', 'whatsapp', 'webchat', 'phone'] as const).map(
            (ch) => {
              const isActive = ch === (currentChannel ?? 'all')
              return (
                <button
                  key={ch}
                  type="button"
                  className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-[0.08em] shrink-0 transition-colors ${
                    isActive
                      ? 'bg-primary text-primary-foreground'
                      : 'text-[color:var(--color-stone)] hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]'
                  }`}
                >
                  {ch === 'all' ? 'ALL' : ch.toUpperCase()}
                </button>
              )
            },
          )}
        </div>
        <div className="flex-1 min-h-0 overflow-hidden">
          <ConversationList
            conversations={conversations}
            studioId={studioId}
            activeConversationId={activeConversationId}
          />
        </div>
        <ShortcutCheatsheet open={showCheatsheet} onClose={() => setShowCheatsheet(false)} />
      </div>
    )
  }

  // ── Desktop / Tablet layout ────────────────────────────────────────────────
  // Context pane: grid col on wide, sheet on tablet
  const contextIsSheet = isTablet && !isWide
  const showContextPane = showContext && !!activeConversation && !!conversationContext

  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Top header */}
      <MessagesHeader
        unreadCounts={unreadCounts}
        onShowCheatsheet={() => setShowCheatsheet(true)}
      />

      {/* 3/4-pane grid */}
      <div
        className="flex-1 min-h-0 grid overflow-hidden transition-[grid-template-columns] duration-150 ease-out"
        style={{
          gridTemplateColumns:
            showContextPane && !contextIsSheet
              ? '72px 360px minmax(0,1fr) 380px'
              : '72px 360px minmax(0,1fr)',
        }}
      >
        {/* Rail */}
        <ChannelRail
          unreadCounts={unreadCounts}
          currentChannel={currentChannel}
        />

        {/* List */}
        <ConversationList
          conversations={conversations}
          studioId={studioId}
          activeConversationId={activeConversationId}
        />

        {/* Thread panel */}
        {activeConversation ? (
          <ThreadPanel
            conversation={activeConversation}
            initialMessages={activeMessages}
            conversationContext={conversationContext}
            templates={templates}
            initialSmartReplies={smartReplies}
            studioId={studioId}
            currentUserId={currentUserId}
            currentUserName={currentUserName}
            members={members}
            showContextPane={showContextPane}
            onToggleContext={() => setShowContext((v) => !v)}
          />
        ) : (
          <EmptyThreadState hasConversations={conversations.length > 0} />
        )}

        {/* Context pane (grid col — desktop only) */}
        {showContextPane && !contextIsSheet && conversationContext && (
          <ContextPane
            context={conversationContext}
            conversationId={activeConversationId ?? ''}
            onClose={() => setShowContext(false)}
          />
        )}
      </div>

      {/* Context pane as sheet (tablet) */}
      {contextIsSheet && conversationContext && (
        <ContextPane
          context={conversationContext}
          conversationId={activeConversationId ?? ''}
          onClose={() => setShowContext(false)}
          renderAsSheet
          sheetOpen={showContextPane}
        />
      )}

      <ShortcutCheatsheet open={showCheatsheet} onClose={() => setShowCheatsheet(false)} />
    </div>
  )
}

// ─── EmptyThreadState ─────────────────────────────────────────────────────────

function EmptyThreadState({ hasConversations }: { hasConversations: boolean }) {
  return (
    <div className="flex flex-col items-center justify-center h-full text-center px-8 bg-background">
      <h2 className="font-serif italic text-foreground text-xl mb-2">
        {hasConversations ? 'Select a conversation.' : 'No messages yet.'}
      </h2>
      <p className="text-sm text-[color:var(--color-stone)] max-w-xs">
        {hasConversations
          ? 'Choose a conversation from the list to view messages.'
          : 'When clients message you via SMS or email, conversations will appear here.'}
      </p>
    </div>
  )
}

'use client'

/**
 * Composer — full-featured compose area at the bottom of ThreadPanel.
 *
 * Features:
 * - Channel switcher (SMS / Email)
 * - "/" trigger opens TemplatePopover
 * - Internal-note toggle (changes bg + button label)
 * - Schedule send popover
 * - Optimistic send
 * - ⌘+Enter to send
 */

import { useState, useRef, useCallback, useTransition, useEffect } from 'react'
import { StickyNote, Paperclip, Clock, Command as CommandIcon } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import {
  sendMessageAction,
  sendInternalNoteAction,
  scheduleSendAction,
} from '@/app/(app)/messages/actions'
import type { ConversationMessage } from '@/lib/messaging/queries'
import type { MessageTemplate } from '@/lib/supabase/types'
import { ChannelSwitcher } from './ChannelSwitcher'
import { TemplatePopover } from './TemplatePopover'
import { ScheduleSendPopover } from './ScheduleSendPopover'
import type { Channel } from '@/lib/messaging/queries'

// ─── Props ────────────────────────────────────────────────────────────────────

interface ComposerProps {
  conversationId: string
  clientId: string
  channel: Channel
  clientFirstName?: string | undefined
  clientHasPhone: boolean
  clientHasEmail: boolean
  templates: MessageTemplate[]
  onOptimisticSend: (msg: ConversationMessage) => void
  onInternalNoteModeChange?: ((isInternal: boolean) => void) | undefined
  disabled?: boolean | undefined
}

// ─── Component ────────────────────────────────────────────────────────────────

export function Composer({
  conversationId,
  clientId,
  channel: initialChannel,
  clientFirstName = 'Client',
  clientHasPhone,
  clientHasEmail,
  templates,
  onOptimisticSend,
  onInternalNoteModeChange,
  disabled = false,
}: ComposerProps) {
  const [body, setBody] = useState('')
  const [isInternalNote, setIsInternalNote] = useState(false)
  const [templatePopoverOpen, setTemplatePopoverOpen] = useState(false)
  const [activeChannel, setActiveChannel] = useState<'sms' | 'email'>(
    initialChannel === 'email' ? 'email' : 'sms',
  )
  const [isPending, startTransition] = useTransition()
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  // Keep channel in sync when conversation changes
  useEffect(() => {
    setActiveChannel(initialChannel === 'email' ? 'email' : 'sms')
    setBody('')
    setIsInternalNote(false)
  }, [conversationId, initialChannel])

  // Notify parent when internal-note mode changes
  useEffect(() => {
    onInternalNoteModeChange?.(isInternalNote)
  }, [isInternalNote, onInternalNoteModeChange])

  const autoResize = useCallback((el: HTMLTextAreaElement) => {
    el.style.height = 'auto'
    el.style.height = `${Math.min(el.scrollHeight, 240)}px`
  }, [])

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const value = e.target.value
      setBody(value)
      autoResize(e.target)

      // "/" at start of empty line triggers template popover
      if (value === '/' && !isInternalNote) {
        setTemplatePopoverOpen(true)
        setBody('')
      }
    },
    [autoResize, isInternalNote],
  )

  const handleTemplateSelect = useCallback(
    (resolvedBody: string) => {
      setBody(resolvedBody)
      setTimeout(() => {
        const el = textareaRef.current
        if (el) {
          el.focus()
          autoResize(el)
          el.setSelectionRange(resolvedBody.length, resolvedBody.length)
        }
      }, 0)
    },
    [autoResize],
  )

  const handleSend = useCallback(() => {
    const trimmed = body.trim()
    if (!trimmed || isPending || disabled) return

    const optimisticMsg: ConversationMessage = {
      id: `optimistic-${Date.now()}`,
      conversation_id: conversationId,
      channel: (isInternalNote ? 'in_app' : activeChannel) as ConversationMessage['channel'],
      direction: 'outbound',
      subject: null,
      body: trimmed,
      status: 'queued',
      sent_at: null,
      delivered_at: null,
      opened_at: null,
      error: null,
      provider_message_id: null,
      metadata: isInternalNote ? { auto_reply: false } : {},
      is_internal_note: isInternalNote,
      scheduled_for: null,
      reply_to_message_id: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }

    onOptimisticSend(optimisticMsg)
    setBody('')
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
    }

    startTransition(async () => {
      if (isInternalNote) {
        const result = await sendInternalNoteAction({
          conversationId,
          clientId,
          body: trimmed,
        })
        if (!result.ok) toast.error(result.error ?? 'Failed to save note')
        return
      }

      const result = await sendMessageAction({
        conversationId,
        clientId,
        body: trimmed,
        channel: activeChannel,
      })
      if (!result.ok) toast.error(result.error ?? 'Failed to send message')
    })
  }, [body, isPending, disabled, conversationId, clientId, activeChannel, isInternalNote, onOptimisticSend])

  const handleSchedule = useCallback(
    (scheduledFor: string) => {
      const trimmed = body.trim()
      if (!trimmed || isPending || disabled) return

      startTransition(async () => {
        const result = await scheduleSendAction({
          conversationId,
          clientId,
          body: trimmed,
          channel: activeChannel,
          scheduledFor,
        })
        if (!result.ok) {
          toast.error(result.error ?? 'Failed to schedule message')
          return
        }
        toast.success('Message scheduled')
        setBody('')
        if (textareaRef.current) {
          textareaRef.current.style.height = 'auto'
        }
      })
    },
    [body, isPending, disabled, conversationId, clientId, activeChannel],
  )

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
        e.preventDefault()
        handleSend()
        return
      }
      if (e.key === 'Escape') {
        if (isInternalNote) {
          setIsInternalNote(false)
        } else if (templatePopoverOpen) {
          setTemplatePopoverOpen(false)
        }
      }
    },
    [handleSend, isInternalNote, templatePopoverOpen],
  )

  const canSend = body.trim().length > 0 && !isPending && !disabled
  const isSmsMode = activeChannel === 'sms' && !isInternalNote
  const sendLabel = isInternalNote ? 'Save note' : 'Send'

  return (
    <div
      className={cn(
        'border-t border-border px-3 py-3 transition-colors',
        isInternalNote
          ? 'bg-[color-mix(in_srgb,var(--color-stone)_10%,transparent)] border-dashed border-[color:var(--color-stone)]'
          : 'bg-background',
      )}
    >
      {/* Internal note caption */}
      {isInternalNote && (
        <p className="text-xs italic text-[color:var(--color-stone)] mb-2">
          Staff only — this note stays in the studio.
        </p>
      )}

      {/* Textarea */}
      <div className="relative mb-2">
        <textarea
          ref={textareaRef}
          value={body}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          placeholder={
            isInternalNote
              ? 'Add a staff note…'
              : `Type a ${activeChannel === 'sms' ? 'message' : 'email'}… (/ for templates, ⌘+Enter to send)`
          }
          rows={2}
          disabled={disabled || isPending}
          aria-label={isInternalNote ? 'Internal note body' : 'Message body'}
          className={cn(
            'w-full resize-none border-0 bg-transparent px-1 py-1 text-sm',
            'placeholder:text-[color:var(--color-stone)] focus-visible:outline-none',
            'disabled:opacity-50 disabled:cursor-not-allowed',
            'min-h-[68px] max-h-[240px] overflow-y-auto',
          )}
          style={{ height: 'auto' }}
        />
        {/* SMS char counter */}
        {isSmsMode && body.length > 0 && (
          <span
            className={cn(
              'absolute right-1 bottom-1 text-[10px]',
              body.length > 160 ? 'text-[color:var(--color-rust)]' : 'text-[color:var(--color-stone)]',
            )}
          >
            {body.length}
            {body.length > 160 && ` (${Math.ceil(body.length / 160)} seg)`}
          </span>
        )}
      </div>

      {/* Tools bar */}
      <div className="flex items-center gap-1 flex-wrap">
        {/* Channel switcher */}
        {!isInternalNote && (
          <>
            <ChannelSwitcher
              current={activeChannel}
              hasPhone={clientHasPhone}
              hasEmail={clientHasEmail}
              onChange={setActiveChannel}
              disabled={disabled}
            />
            <Separator orientation="vertical" className="h-5 mx-1" />
          </>
        )}

        {/* Templates button */}
        {!isInternalNote && (
          <TemplatePopover
            templates={templates}
            clientFirstName={clientFirstName ?? null}
            open={templatePopoverOpen}
            onOpenChange={setTemplatePopoverOpen}
            onSelect={handleTemplateSelect}
          >
            <button
              type="button"
              disabled={disabled}
              aria-label="Insert template"
              className="inline-flex items-center gap-1 px-2 py-1 h-7 text-xs font-medium text-[color:var(--color-stone)] rounded-md hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors disabled:opacity-50"
            >
              <CommandIcon className="h-3.5 w-3.5" aria-hidden />
              Templates
            </button>
          </TemplatePopover>
        )}

        {/* Attach (stub) */}
        <Tooltip>
          <TooltipTrigger
            disabled={disabled}
            aria-label="Attach file"
            className="inline-flex items-center justify-center h-7 w-7 text-[color:var(--color-stone)] rounded-md hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors disabled:opacity-50"
          >
            <Paperclip className="h-3.5 w-3.5" aria-hidden />
          </TooltipTrigger>
          <TooltipContent>Attach file</TooltipContent>
        </Tooltip>

        {/* Internal note toggle */}
        <Tooltip>
          <TooltipTrigger
            onClick={() => setIsInternalNote((v) => !v)}
            disabled={disabled}
            aria-label={isInternalNote ? 'Exit staff note mode' : 'Add staff note'}
            aria-pressed={isInternalNote}
            className={cn(
              'inline-flex items-center justify-center h-7 w-7 rounded-md transition-colors disabled:opacity-50',
              isInternalNote
                ? 'bg-[color-mix(in_srgb,var(--color-stone)_16%,transparent)] text-foreground'
                : 'text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
            )}
          >
            <StickyNote className="h-3.5 w-3.5" aria-hidden />
          </TooltipTrigger>
          <TooltipContent>Staff-only note</TooltipContent>
        </Tooltip>

        {/* Schedule send (hidden in internal-note mode) */}
        {!isInternalNote && (
          <ScheduleSendPopover onSchedule={handleSchedule} disabled={disabled || !canSend}>
            <Tooltip>
              <TooltipTrigger
                disabled={disabled || !canSend}
                aria-label="Schedule send"
                className="inline-flex items-center justify-center h-7 w-7 text-[color:var(--color-stone)] rounded-md hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors disabled:opacity-50"
              >
                <Clock className="h-3.5 w-3.5" aria-hidden />
              </TooltipTrigger>
              <TooltipContent>Schedule send</TooltipContent>
            </Tooltip>
          </ScheduleSendPopover>
        )}

        {/* Spacer */}
        <div className="flex-1" />

        {/* Send button */}
        <Button
          size="sm"
          className="h-7 px-3 text-xs"
          disabled={!canSend}
          onClick={handleSend}
          aria-label={sendLabel}
        >
          {isPending ? (
            <span className="animate-pulse">
              {isInternalNote ? 'Saving…' : 'Sending…'}
            </span>
          ) : (
            sendLabel
          )}
        </Button>
      </div>
    </div>
  )
}

/**
 * Messaging mutations — server-side only.
 *
 * Each function takes studioId to ensure all mutations are scoped.
 * Uses authenticated client — RLS enforces write access.
 */

import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import type {
  TriageTag,
  MessageTemplate,
  MessageTemplateUpdate,
  AutoReplyRule,
  AutoReplyRuleUpdate,
} from '@/lib/supabase/types'

// ─── markConversationRead ─────────────────────────────────────────────────────

export async function markConversationRead(
  studioId: string,
  conversationId: string,
): Promise<void> {
  const supabase = await createClient()

  // Verify studio ownership before calling RPC
  const { data: conv } = await supabase
    .from('conversations')
    .select('id, studio_id')
    .eq('id', conversationId)
    .eq('studio_id', studioId)
    .single()

  if (!conv) {
    logger.warn({ conversationId, studioId }, 'messaging: markConversationRead — not found or wrong studio')
    return
  }

  const { error } = await supabase.rpc('mark_conversation_read', {
    p_conversation_id: conversationId,
  })

  if (error) {
    logger.error({ err: error, conversationId }, 'messaging: markConversationRead RPC failed')
  }
}

// ─── assignConversation ───────────────────────────────────────────────────────

export async function assignConversation(
  studioId: string,
  conversationId: string,
  userId: string | null,
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('conversations')
    .update({ assigned_to: userId })
    .eq('id', conversationId)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, conversationId, userId }, 'messaging: assignConversation failed')
    throw new Error('Failed to assign conversation')
  }
}

