// ─── createMessageTemplate ────────────────────────────────────────────────────

export type CreateMessageTemplateInput = {
  name: string
  slug: string
  body: string
  channel: MessageTemplate['channel']
  category: MessageTemplate['category']
  trigger_keywords?: string[] | undefined
  is_default?: boolean | undefined
}

export async function createMessageTemplate(
  studioId: string,
  input: CreateMessageTemplateInput,
  userId: string,
): Promise<MessageTemplate> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('message_templates')
    .insert({
      studio_id: studioId,
      name: input.name,
      slug: input.slug,
      body: input.body,
      channel: input.channel,
      category: input.category,
      trigger_keywords: input.trigger_keywords ?? [],
      is_default: input.is_default ?? false,
      created_by: userId,
    })
    .select('*')
    .single()

  if (error || !data) {
    logger.error({ err: error, studioId }, 'messaging: createMessageTemplate failed')
    throw new Error('Failed to create message template')
  }

  return data as MessageTemplate
}

// ─── updateMessageTemplate ────────────────────────────────────────────────────

export type UpdateMessageTemplateInput = {
  name?: string | undefined
  slug?: string | undefined
  body?: string | undefined
  channel?: MessageTemplate['channel'] | undefined
  category?: MessageTemplate['category'] | undefined
  trigger_keywords?: string[] | undefined
  is_default?: boolean | undefined
}

export async function updateMessageTemplate(
  studioId: string,
  id: string,
  patch: UpdateMessageTemplateInput,
): Promise<void> {
  const supabase = await createClient()

  // Build update payload — only include defined fields (exactOptionalPropertyTypes)
  const payload: MessageTemplateUpdate = { updated_at: new Date().toISOString() }
  if (patch.name !== undefined) payload.name = patch.name
  if (patch.slug !== undefined) payload.slug = patch.slug
  if (patch.body !== undefined) payload.body = patch.body
  if (patch.channel !== undefined) payload.channel = patch.channel
  if (patch.category !== undefined) payload.category = patch.category
  if (patch.trigger_keywords !== undefined) payload.trigger_keywords = patch.trigger_keywords
  if (patch.is_default !== undefined) payload.is_default = patch.is_default

  const { error } = await supabase
    .from('message_templates')
    .update(payload)
    .eq('id', id)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, id, studioId }, 'messaging: updateMessageTemplate failed')
    throw new Error('Failed to update message template')
  }
}

// ─── deleteMessageTemplate ────────────────────────────────────────────────────

export async function deleteMessageTemplate(studioId: string, id: string): Promise<void> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('message_templates')
    .delete({ count: 'exact' })
    .eq('id', id)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, id, studioId }, 'messaging: deleteMessageTemplate failed')
    throw new Error('Failed to delete message template')
  }

  if (count === 0) {
    throw new Error('Template not found or access denied')
  }
}

