}

// ─── toggleAutoReplyRule ──────────────────────────────────────────────────────

export async function toggleAutoReplyRule(
  studioId: string,
  id: string,
  enabled: boolean,
): Promise<void> {
  const supabase = await createClient()

  const { error } = await supabase
    .from('auto_reply_rules')
    .update({ enabled, updated_at: new Date().toISOString() })
    .eq('id', id)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, id, enabled, studioId }, 'messaging: toggleAutoReplyRule failed')
    throw new Error('Failed to toggle auto-reply rule')
  }
}

// ─── deleteAutoReplyRule ──────────────────────────────────────────────────────

export async function deleteAutoReplyRule(studioId: string, id: string): Promise<void> {
  const supabase = await createClient()

  const { count, error } = await supabase
    .from('auto_reply_rules')
    .delete({ count: 'exact' })
    .eq('id', id)
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, id, studioId }, 'messaging: deleteAutoReplyRule failed')
    throw new Error('Failed to delete auto-reply rule')
  }

  if (count === 0) {
    throw new Error('Auto-reply rule not found or access denied')
  }
}

// ─── scheduleMessage ──────────────────────────────────────────────────────────

export interface ScheduleMessageParams {
  conversationId: string
  clientId: string
  body: string
  channel: 'sms' | 'email'
  scheduledFor: string  // ISO timestamp
  userId: string
}

export async function scheduleMessage(
  studioId: string,
  params: ScheduleMessageParams,
): Promise<{ commId: string }> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: params.clientId,
      conversation_id: params.conversationId,
      channel: params.channel,
      direction: 'outbound',
      body: params.body,
      status: 'queued',
      is_internal_note: false,
      scheduled_for: params.scheduledFor,
      metadata: {},
    })
    .select('id')
    .single()

  if (error || !data) {
    logger.error({ err: error, studioId }, 'messaging: scheduleMessage failed')
    throw new Error('Failed to schedule message')
  }

  return { commId: data.id }
}

