'use server'

/**
 * Messages server actions — all mutations go through here.
 *
 * Each action:
 *  - Resolves studioId from authenticated session
 *  - Validates input with Zod
 *  - Returns { ok, data?, error? }
 *  - Calls revalidatePath where appropriate
 */

import { revalidatePath } from 'next/cache'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { sendSmsToClient, sendEmailToClient, sendInternalNote } from '@/lib/messaging/send'
import {
  markConversationRead,
  assignConversation,
  archiveConversation,
  starConversation,
  linkConversationToClient,
  setTriageTag,
  resolveConversation,
  unresolveConversation,
  toggleInternalNote,
  createMessageTemplate,
  updateMessageTemplate,
  deleteMessageTemplate,
  createAutoReplyRule,
  updateAutoReplyRule,
  toggleAutoReplyRule,
  deleteAutoReplyRule,
  scheduleMessage,
} from '@/lib/messaging/mutations'
import { listMessageTemplates } from '@/lib/messaging/queries'
import { seedDefaultTemplates } from '@/lib/messaging/templates-seed'
import { enqueueScheduledMessage } from '@/lib/queue'
import { logger } from '@/lib/logger'
import type { SmartReplyAction } from '@/lib/messaging/triage'
import type { TriageTag } from '@/lib/messaging/queries'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ActionResult<T = undefined> {
  ok: boolean
  data?: T | undefined
  error?: string | undefined
}

// ─── Internal type for studios messaging patch ────────────────────────────────

type StudioMessagingPatch = {
  email_signature?: string
  messaging_business_hours?: Record<string, { open: string; close: string }>
  messaging_tone?: 'casual' | 'formal'
}

// ─── Revalidate helper ────────────────────────────────────────────────────────

function revalidateMessages() {
  revalidatePath('/messages')
  revalidatePath('/settings/messaging')
}

// ─── sendMessageAction ────────────────────────────────────────────────────────

const SendMessageSchema = z.object({
  conversationId: z.string().uuid(),
  clientId: z.string().uuid(),
  body: z.string().min(1).max(1600),
  channel: z.enum(['sms', 'email']),
  subject: z.string().max(200).optional(),
})

export async function sendMessageAction(
  input: z.infer<typeof SendMessageSchema>,
): Promise<ActionResult<{ commId: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = SendMessageSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { conversationId, clientId, body, channel, subject } = parsed.data
  const { studioId } = authUser

  try {
    if (channel === 'sms') {
      const result = await sendSmsToClient(
        { studioId, clientId, body },
        authUser.user.id,
      )
      if (!result.ok) {
        return { ok: false, error: result.error ?? 'Failed to send SMS' }
      }
      revalidateMessages()
      return { ok: true, data: { commId: result.commId ?? '' } }
    }

    if (channel === 'email') {
      const result = await sendEmailToClient(
        {
          studioId,
          clientId,
          subject: subject ?? '(no subject)',
          body,
        },
        authUser.user.id,
      )
      if (!result.ok) {
        return { ok: false, error: result.error ?? 'Failed to send email' }
      }
      revalidateMessages()
      return { ok: true, data: { commId: result.commId ?? '' } }
    }

    return { ok: false, error: 'Unsupported channel' }
  } catch (err) {
    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
    return { ok: false, error: 'Failed to send message' }
  }
}

// ─── sendInternalNoteAction ───────────────────────────────────────────────────

const SendInternalNoteSchema = z.object({
  conversationId: z.string().uuid(),
  clientId: z.string().uuid(),
  body: z.string().min(1).max(4000),
})

export async function sendInternalNoteAction(
  input: z.infer<typeof SendInternalNoteSchema>,
): Promise<ActionResult<{ commId: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = SendInternalNoteSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  try {
    const result = await sendInternalNote(
      authUser.studioId,
      {
        conversationId: parsed.data.conversationId,
        clientId: parsed.data.clientId,
        body: parsed.data.body,
      },
      authUser.user.id,
    )

    if (!result.ok) {
      return { ok: false, error: result.error ?? 'Failed to save internal note' }
    }

    revalidateMessages()
    return { ok: true, data: { commId: result.commId ?? '' } }
  } catch (err) {
    logger.error({ err }, 'sendInternalNoteAction: unexpected error')
    return { ok: false, error: 'Failed to save internal note' }
  }
}

// ─── scheduleSendAction ───────────────────────────────────────────────────────

const ScheduleSendSchema = z.object({
  conversationId: z.string().uuid(),
  clientId: z.string().uuid(),
  body: z.string().min(1).max(1600),
  channel: z.enum(['sms', 'email']),
  scheduledFor: z.string().datetime(),
})

export async function scheduleSendAction(
  input: z.infer<typeof ScheduleSendSchema>,
): Promise<ActionResult<{ commId: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = ScheduleSendSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  try {
    const { commId } = await scheduleMessage(authUser.studioId, {
      conversationId: parsed.data.conversationId,
      clientId: parsed.data.clientId,
      body: parsed.data.body,
      channel: parsed.data.channel,
      scheduledFor: parsed.data.scheduledFor,
      userId: authUser.user.id,
    })

    // Enqueue delayed BullMQ job
    await enqueueScheduledMessage(commId, authUser.studioId, parsed.data.scheduledFor)

    revalidateMessages()
    return { ok: true, data: { commId } }
  } catch (err) {
    logger.error({ err }, 'scheduleSendAction: unexpected error')
    return { ok: false, error: 'Failed to schedule message' }
  }
}

// ─── setTriageTagAction ───────────────────────────────────────────────────────

const SetTriageTagSchema = z.object({
  conversationId: z.string().uuid(),
  tag: z
    .enum(['inquiry', 'booking', 'client', 'rescheduling', 'pricing', 'deposit_paid', 'missed_call'])
    .nullable(),
})

export async function setTriageTagAction(
  input: z.infer<typeof SetTriageTagSchema>,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = SetTriageTagSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  try {
    await setTriageTag(
      authUser.studioId,
      parsed.data.conversationId,
      parsed.data.tag as TriageTag | null,
    )
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err }, 'setTriageTagAction: failed')
    return { ok: false, error: 'Failed to set triage tag' }
  }
}

// ─── resolveAction / unresolveAction ─────────────────────────────────────────

export async function resolveAction(conversationId: string): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await resolveConversation(authUser.studioId, conversationId)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId }, 'resolveAction: failed')
    return { ok: false, error: 'Failed to resolve conversation' }
  }
}

export async function unresolveAction(conversationId: string): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await unresolveConversation(authUser.studioId, conversationId)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId }, 'unresolveAction: failed')
    return { ok: false, error: 'Failed to unresolve conversation' }
  }
}

// ─── fireSmartReplyAction ─────────────────────────────────────────────────────

const FireSmartReplySchema = z.object({
  conversationId: z.string().uuid(),
  action: z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('send_template'), templateSlug: z.string().min(1) }),
    z.object({ kind: z.literal('open_calendar_reschedule'), bookingId: z.string().uuid() }),
    z.object({ kind: z.literal('share_portfolio') }),
    z.object({ kind: z.literal('offer_slots'), days: z.union([z.literal(1), z.literal(3), z.literal(7)]) }),
    z.object({ kind: z.literal('send_aftercare_pdf') }),
    z.object({ kind: z.literal('request_deposit') }),
  ]),
  clientId: z.string().uuid(),
  channel: z.enum(['sms', 'email']).default('sms'),
})

export async function fireSmartReplyAction(
  input: z.infer<typeof FireSmartReplySchema>,
): Promise<ActionResult<{ commId?: string | undefined; navigateTo?: string | undefined }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = FireSmartReplySchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { conversationId, action, clientId, channel } = parsed.data
  const { studioId } = authUser

  try {
    // Navigation actions — return route for client-side navigation
    if (action.kind === 'open_calendar_reschedule') {
      return {
        ok: true,
        data: { navigateTo: `/calendar?rescheduleBooking=${action.bookingId}` },
      }
    }

    // Slot-offer action — render placeholder from template
    if (action.kind === 'offer_slots') {
      const templates = await listMessageTemplates(studioId, { category: 'reschedule' })
      const tpl = templates[0]
      if (!tpl) {
        return { ok: false, error: 'Reschedule template not found. Add one in Settings → Messaging.' }
      }
      const result = await sendSmsToClient(
        { studioId, clientId, body: tpl.body },
        authUser.user.id,
      )
      if (!result.ok) return { ok: false, error: result.error }
      revalidateMessages()
      return { ok: true, data: { commId: result.commId } }
    }

    // Template-based actions — map slug to send
    let templateSlug: string | null = null

    if (action.kind === 'send_template') {
      templateSlug = action.templateSlug
    } else if (action.kind === 'send_aftercare_pdf') {
      templateSlug = 'aftercare-guide'
    } else if (action.kind === 'request_deposit') {
      templateSlug = 'deposit-request'
    } else if (action.kind === 'share_portfolio') {
      templateSlug = 'portfolio-share'
    }

    if (!templateSlug) {
      return { ok: false, error: 'Unknown smart reply action' }
    }

    const templates = await listMessageTemplates(studioId)
    const tpl = templates.find((t) => t.slug === templateSlug)

    if (!tpl) {
      return { ok: false, error: `Template '${templateSlug}' not found. Check Settings → Messaging.` }
    }

    let result: Awaited<ReturnType<typeof sendSmsToClient>>

    if (channel === 'email') {
      result = await sendEmailToClient(
        { studioId, clientId, subject: tpl.name, body: tpl.body },
        authUser.user.id,
      )
    } else {
      result = await sendSmsToClient(
        { studioId, clientId, body: tpl.body },
        authUser.user.id,
      )
    }

    if (!result.ok) return { ok: false, error: result.error }

    revalidateMessages()
    return { ok: true, data: { commId: result.commId } }
  } catch (err) {
    logger.error({ err, conversationId }, 'fireSmartReplyAction: unexpected error')
    return { ok: false, error: 'Failed to send smart reply' }
  }
}

// ─── markReadAction ───────────────────────────────────────────────────────────

export async function markReadAction(conversationId: string): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await markConversationRead(authUser.studioId, conversationId)
    revalidatePath('/messages')
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId }, 'markReadAction: failed')
    return { ok: false, error: 'Failed to mark as read' }
  }
}

// ─── assignAction ─────────────────────────────────────────────────────────────

export async function assignAction(
  conversationId: string,
  userId: string | null,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await assignConversation(authUser.studioId, conversationId, userId)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId }, 'assignAction: failed')
    return { ok: false, error: 'Failed to assign conversation' }
  }
}

// ─── archiveAction ────────────────────────────────────────────────────────────

export async function archiveAction(conversationId: string): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await archiveConversation(authUser.studioId, conversationId)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId }, 'archiveAction: failed')
    return { ok: false, error: 'Failed to archive conversation' }
  }
}

// ─── starAction ───────────────────────────────────────────────────────────────

export async function starAction(
  conversationId: string,
  starred: boolean,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await starConversation(authUser.studioId, conversationId, starred)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId }, 'starAction: failed')
    return { ok: false, error: 'Failed to star/unstar conversation' }
  }
}

// ─── linkClientAction ─────────────────────────────────────────────────────────

export async function linkClientAction(
  conversationId: string,
  clientId: string,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await linkConversationToClient(authUser.studioId, conversationId, clientId)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, conversationId, clientId }, 'linkClientAction: failed')
    return { ok: false, error: 'Failed to link client' }
  }
}

// ─── Template CRUD actions ────────────────────────────────────────────────────

const CreateTemplateSchema = z.object({
  name: z.string().min(1).max(100),
  slug: z.string().min(1).max(100).regex(/^[a-z0-9-]+$/, 'Slug must be lowercase letters, numbers, and hyphens only'),
  body: z.string().min(1).max(4000),
  channel: z.enum(['sms', 'email', 'both']),
  category: z.enum(['aftercare', 'deposit', 'booking', 'portfolio', 'reschedule', 'inquiry_reply', 'custom']),
  trigger_keywords: z.array(z.string()).optional(),
  is_default: z.boolean().optional(),
})

export async function createTemplateAction(
  input: z.infer<typeof CreateTemplateSchema>,
): Promise<ActionResult<{ id: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = CreateTemplateSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  try {
    const tpl = await createMessageTemplate(authUser.studioId, parsed.data, authUser.user.id)
    revalidateMessages()
    return { ok: true, data: { id: tpl.id } }
  } catch (err) {
    logger.error({ err }, 'createTemplateAction: failed')
    return { ok: false, error: 'Failed to create template' }
  }
}

const UpdateTemplateSchema = z.object({
  id: z.string().uuid(),
  name: z.string().min(1).max(100).optional(),
  slug: z.string().min(1).max(100).regex(/^[a-z0-9-]+$/).optional(),
  body: z.string().min(1).max(4000).optional(),
  channel: z.enum(['sms', 'email', 'both']).optional(),
  category: z.enum(['aftercare', 'deposit', 'booking', 'portfolio', 'reschedule', 'inquiry_reply', 'custom']).optional(),
  trigger_keywords: z.array(z.string()).optional(),
  is_default: z.boolean().optional(),
})

export async function updateTemplateAction(
  input: z.infer<typeof UpdateTemplateSchema>,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = UpdateTemplateSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { id, ...patch } = parsed.data

  try {
    await updateMessageTemplate(authUser.studioId, id, patch)
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err, id }, 'updateTemplateAction: failed')
    return { ok: false, error: 'Failed to update template' }
  }
}

export async function deleteTemplateAction(id: string): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  try {
    await deleteMessageTemplate(authUser.studioId, id)
    revalidateMessages()
    return { ok: true }
