)

const UpdateStudioMessagingSchema = z.object({
  signature: z.string().max(2000).optional(),
  businessHours: BusinessHoursSchema.optional(),
  tone: z.enum(['casual', 'formal']).optional(),
})

export async function updateStudioMessagingAction(
  input: z.infer<typeof UpdateStudioMessagingSchema>,
): Promise<ActionResult> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = UpdateStudioMessagingSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const patch: StudioMessagingPatch = {}
  if (parsed.data.signature !== undefined) patch.email_signature = parsed.data.signature
  if (parsed.data.businessHours !== undefined) patch.messaging_business_hours = parsed.data.businessHours
  if (parsed.data.tone !== undefined) patch.messaging_tone = parsed.data.tone

  if (Object.keys(patch).length === 0) return { ok: true }

  try {
    const supabase = await (await import('@/lib/supabase/server')).createClient()
    const { error } = await supabase
      .from('studios')
      .update(patch)
      .eq('id', authUser.studioId)
    if (error) throw error
    revalidateMessages()
    return { ok: true }
  } catch (err) {
    logger.error({ err }, 'updateStudioMessagingAction: failed')
    return { ok: false, error: 'Failed to save messaging settings' }
  }
}

'use client'

/**
 * useConversationPresence — Supabase Realtime presence per conversation.
 *
 * Tracks who is viewing and typing in the active conversation.
 * Excludes the current user from returned arrays.
 * Throttles typing state to 1 send per 2s.
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { PresenceUser } from '@/components/messages/PresenceStrip'

const TYPING_THROTTLE_MS = 2000

function presenceChannelName(conversationId: string): string {
  return `presence:conversation:${conversationId}`
}

interface UseConversationPresenceReturn {
  viewers: PresenceUser[]
  typing: PresenceUser[]
  setTyping: (isTyping: boolean) => void
}

export function useConversationPresence(
  conversationId: string | null,
  currentUserId: string,
  currentUserName: string,
): UseConversationPresenceReturn {
  const [viewers, setViewers] = useState<PresenceUser[]>([])
  const [typing, setTypingState] = useState<PresenceUser[]>([])
  const lastTypingSentAt = useRef<number>(0)
  const channelRef = useRef<ReturnType<ReturnType<typeof createClient>['channel']> | null>(null)

  useEffect(() => {
    if (!conversationId) {
      setViewers([])
      setTypingState([])
      return
    }

    const supabase = createClient()
    const channelName = presenceChannelName(conversationId)

    const ch = supabase.channel(channelName, {
      config: { presence: { key: currentUserId } },
    })

    channelRef.current = ch

    ch.on('presence', { event: 'sync' }, () => {
      const state = ch.presenceState<{ userId: string; userName: string; state: 'viewing' | 'typing' }>()

      const allUsers: PresenceUser[] = Object.values(state).flatMap((presences) =>
        presences.map((p) => ({ userId: p.userId, userName: p.userName, state: p.state })),
      )

      // Exclude current user
      const others = allUsers.filter((u) => u.userId !== currentUserId)

      setViewers(others.filter((u) => u.state === 'viewing'))
      setTypingState(others.filter((u) => u.state === 'typing'))
    })

    ch.subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        void ch.track({
          userId: currentUserId,
          userName: currentUserName,
          state: 'viewing',
          ts: Date.now(),
        })
      }
    })

    return () => {
      void supabase.removeChannel(ch)
      channelRef.current = null
    }
  }, [conversationId, currentUserId, currentUserName])

  const setTyping = useCallback(
    (isTyping: boolean) => {
      const ch = channelRef.current
      if (!ch) return

      const now = Date.now()
      if (isTyping && now - lastTypingSentAt.current < TYPING_THROTTLE_MS) return

      lastTypingSentAt.current = now

      void ch.track({
        userId: currentUserId,
        userName: currentUserName,
        state: isTyping ? 'typing' : 'viewing',
        ts: now,
      })
    },
    [currentUserId, currentUserName],
  )

  return { viewers, typing, setTyping }
}

'use client'

/**
 * ThreadPanel — active conversation view.
 *
 * Header: avatar + name + triage pill + next-booking context
 *         + Assign / Star / Info / MoreVertical actions
 * Body: date-separated message bubbles
 * Footer: PresenceStrip → SmartReplyChips → Composer
 *
 * Subscribes to Realtime inserts + presence.
 * Marks conversation read on mount when unread > 0.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { format, isToday, isYesterday, isSameDay } from 'date-fns'
import {
  ChevronLeft,
  MoreVertical,
  Star,
  Archive,
  Info,
  UserCheck,
  Check,
  X,
  AlertCircle,
} from 'lucide-react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Avatar, AvatarFallback } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Separator } from '@/components/ui/separator'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { MessageBubble } from './MessageBubble'
import { PresenceStrip } from './PresenceStrip'
import { SmartReplyChips } from './SmartReplyChips'
import { Composer } from './Composer'
import { TriageTagPill } from './TriageTagPill'
import { useRealtimeMessages } from '@/hooks/use-realtime-messages'
import { useConversationPresence } from '@/hooks/messages/use-conversation-presence'
import { useSmartReplies } from '@/hooks/messages/use-smart-replies'
import { archiveAction, starAction, resolveAction, unresolveAction, markReadAction } from '@/app/(app)/messages/actions'
import type { ConversationWithClient, ConversationMessage, ConversationContext } from '@/lib/messaging/queries'
import type { MessageTemplate } from '@/lib/supabase/types'
import type { SmartReply } from '@/lib/messaging/triage'

// ─── Types ────────────────────────────────────────────────────────────────────

interface StudioMember {
  id: string
  user_id: string
  display_name?: string | null | undefined
  role: string
}

interface ThreadPanelProps {
  conversation: ConversationWithClient
  initialMessages: ConversationMessage[]
  conversationContext: ConversationContext | null
  templates: MessageTemplate[]
  initialSmartReplies: SmartReply[]
  studioId: string
  currentUserId: string
  currentUserName: string
  members: StudioMember[]
  showContextPane: boolean
  onToggleContext: () => void
  showBackButton?: boolean | undefined
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .filter(Boolean)
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

function getDayLabel(dateStr: string): string {
  const d = new Date(dateStr)
  if (isToday(d)) return 'Today'
  if (isYesterday(d)) return 'Yesterday'
  return format(d, 'MMMM d, yyyy')
}

// ─── ThreadPanel ──────────────────────────────────────────────────────────────

export function ThreadPanel({
  conversation,
  initialMessages,
  conversationContext,
  templates,
  initialSmartReplies,
  currentUserId,
  currentUserName,
  showContextPane,
  onToggleContext,
  showBackButton = false,
}: ThreadPanelProps) {
  const router = useRouter()
  const messagesEndRef = useRef<HTMLDivElement>(null)

  const [messages, setMessages] = useState<ConversationMessage[]>(initialMessages)

  // Smart replies
  const { replies: smartReplies } = useSmartReplies(initialSmartReplies)

  // Presence
  const { viewers, typing } = useConversationPresence(
    conversation.id,
    currentUserId,
    currentUserName,
  )

  const client = conversation.client
  const clientName = client
    ? [client.first_name, client.last_name].filter(Boolean).join(' ')
    : conversation.display_name ?? conversation.external_identifier

  // Mark as read on mount
  useEffect(() => {
    if (conversation.unread_count > 0) {
      void markReadAction(conversation.id).catch(() => void 0)
    }
  }, [conversation.id, conversation.unread_count])

  // Sync messages on navigation
  useEffect(() => {
    setMessages(initialMessages)
  }, [initialMessages])

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages.length])

  // Realtime: append new messages
  const handleNewMessage = useCallback((msg: ConversationMessage) => {
    setMessages((prev) => {
      // Remove matching optimistic message
      const withoutOptimistic = prev.filter((m) => {
        if (!m.id.startsWith('optimistic-')) return true
        return !(
          m.body === msg.body &&
          m.direction === msg.direction &&
          Math.abs(new Date(m.created_at).getTime() - new Date(msg.created_at).getTime()) < 30_000
        )
      })
      if (withoutOptimistic.some((m) => m.id === msg.id)) return withoutOptimistic
      return [...withoutOptimistic, msg]
    })
  }, [])

  useRealtimeMessages(conversation.id, handleNewMessage)

  // Optimistic send
  const handleOptimisticSend = useCallback((msg: ConversationMessage) => {
    setMessages((prev) => [...prev, msg])
  }, [])

  // Quick actions
  const handleArchive = useCallback(async () => {
    const result = await archiveAction(conversation.id)
    if (result.ok) {
      toast.success('Conversation archived')
      router.push('/messages')
    } else {
      toast.error(result.error ?? 'Failed to archive')
    }
  }, [conversation.id, router])

  const handleStar = useCallback(async () => {
    const result = await starAction(conversation.id, !conversation.starred)
    if (result.ok) {
      toast.success(conversation.starred ? 'Removed from starred' : 'Starred')
    } else {
      toast.error(result.error ?? 'Failed')
    }
  }, [conversation.id, conversation.starred])

  const handleResolve = useCallback(async () => {
    const isResolved = !!conversation.resolved_at
    const result = isResolved
      ? await unresolveAction(conversation.id)
      : await resolveAction(conversation.id)

    if (result.ok) {
      toast.success(isResolved ? 'Reopened' : 'Resolved')
    } else {
      toast.error(result.error ?? 'Failed')
    }
  }, [conversation.id, conversation.resolved_at])

  // Group messages by day
  const messageGroups: { dayLabel: string; date: Date; messages: ConversationMessage[] }[] = []
  for (const msg of messages) {
    const d = new Date(msg.created_at)
    const last = messageGroups[messageGroups.length - 1]
    if (!last || !isSameDay(last.date, d)) {
      messageGroups.push({ dayLabel: getDayLabel(msg.created_at), date: d, messages: [msg] })
    } else {
      last.messages.push(msg)
    }
  }

  // Next booking quick context
  const nextBooking = conversationContext?.upcomingBookings?.[0]
  const nextBookingLabel = nextBooking?.scheduled_at
    ? format(new Date(nextBooking.scheduled_at), "EEE h:mm aaa · MMM d")
    : null

  const triageTag = conversation.triage_tag ?? null

  return (
    <div className="flex flex-col h-full min-w-0 bg-background">
      {/* Header */}
      <div className="h-14 px-4 border-b border-border bg-background flex items-center justify-between gap-3 shrink-0">
        {/* Left */}
        <div className="flex items-center gap-3 min-w-0">
          {showBackButton && (
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8 shrink-0"
              onClick={() => router.push('/messages')}
              aria-label="Back to conversations"
            >
              <ChevronLeft className="h-4 w-4" aria-hidden />
            </Button>
          )}

          <Avatar className="h-9 w-9 shrink-0">
            <AvatarFallback className="bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground text-xs font-medium">
              {getInitials(clientName)}
            </AvatarFallback>
          </Avatar>

          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <p className="font-bold text-base text-foreground truncate leading-tight">
                {clientName}
              </p>
              {triageTag && <TriageTagPill tag={triageTag} />}
            </div>
            {nextBookingLabel && (
              <p className="text-[11px] text-[color:var(--color-stone)] truncate">
                {nextBookingLabel}
                {nextBooking?.service_name ? ` · ${nextBooking.service_name}` : ''}
              </p>
            )}
          </div>
        </div>

        {/* Right actions */}
        <div className="flex items-center gap-0.5 shrink-0">
          {/* Assign (stub) */}
          <Tooltip>
            <TooltipTrigger
              aria-label="Assign conversation"
              className="h-8 w-8 flex items-center justify-center rounded-md text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors"
            >
              <UserCheck className="h-4 w-4" aria-hidden />
            </TooltipTrigger>
            <TooltipContent>Assign</TooltipContent>
          </Tooltip>

          {/* Star */}
          <Tooltip>
            <TooltipTrigger
              aria-label={conversation.starred ? 'Unstar' : 'Star'}
              aria-pressed={conversation.starred ?? false}
              onClick={() => void handleStar()}
              className="h-8 w-8 flex items-center justify-center rounded-md text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors"
            >
              <Star
                className={cn(
                  'h-4 w-4',
                  conversation.starred && 'fill-[color:var(--color-rust)] text-[color:var(--color-rust)]',
                )}
                aria-hidden
              />
            </TooltipTrigger>
            <TooltipContent>{conversation.starred ? 'Unstar' : 'Star'}</TooltipContent>
          </Tooltip>

          {/* Info / context pane toggle */}
          <Tooltip>
            <TooltipTrigger
              onClick={onToggleContext}
              aria-label={showContextPane ? 'Hide client context' : 'Show client context'}
              aria-pressed={showContextPane}
              className={cn(
                'h-8 w-8 flex items-center justify-center rounded-md transition-colors',
                showContextPane
                  ? 'bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground'
                  : 'text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
              )}
            >
              <Info className="h-4 w-4" aria-hidden />
            </TooltipTrigger>
            <TooltipContent>{showContextPane ? 'Hide context' : 'Show context'}</TooltipContent>
          </Tooltip>

          {/* More */}
          <DropdownMenu>
            <DropdownMenuTrigger
              aria-label="More actions"
              className="h-8 w-8 flex items-center justify-center rounded-md text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)] transition-colors"
            >
              <MoreVertical className="h-4 w-4" aria-hidden />
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-44">
              <DropdownMenuItem onClick={() => void handleResolve()} className="text-xs">
                {conversation.resolved_at ? (
                  <>
                    <X className="h-3.5 w-3.5 mr-2" aria-hidden />
                    Unresolve
                  </>
                ) : (
                  <>
                    <Check className="h-3.5 w-3.5 mr-2" aria-hidden />
                    Resolve
                  </>
                )}
              </DropdownMenuItem>
              <DropdownMenuItem className="text-xs">
                <AlertCircle className="h-3.5 w-3.5 mr-2" aria-hidden />
                Mark unread
              </DropdownMenuItem>
              {client && (
                <DropdownMenuItem
                  className="text-xs cursor-pointer"
                  onClick={() => router.push(`/clients/${client.id}`)}
                >
                  View client profile
                </DropdownMenuItem>
              )}
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={() => void handleArchive()}
                className="text-xs text-[color:var(--color-stone)]"
              >
                <Archive className="h-3.5 w-3.5 mr-2" aria-hidden />
                Archive
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Messages area */}
      <ScrollArea className="flex-1 min-h-0">
        <div className="px-4 py-6 space-y-0">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <p className="font-serif italic text-foreground text-base mb-1">No messages yet.</p>
              <p className="text-sm text-[color:var(--color-stone)]">Start the conversation below.</p>
            </div>
          ) : (
            messageGroups.map((group) => (
              <div key={group.dayLabel}>
                {/* Day separator */}
                <div className="flex items-center gap-3 my-4">
                  <Separator className="flex-1" />
                  <span className="text-[11px] text-[color:var(--color-stone)] font-medium whitespace-nowrap px-1">
                    {group.dayLabel}
                  </span>
                  <Separator className="flex-1" />
                </div>

                {/* Messages in this day */}
                {group.messages.map((msg, i) => {
                  const prev = group.messages[i - 1]
                  const isGrouped =
                    !!prev &&
                    prev.direction === msg.direction &&
                    prev.is_internal_note === msg.is_internal_note
                  return <MessageBubble key={msg.id} message={msg} isGrouped={isGrouped} />
                })}
              </div>
            ))
          )}
          <div ref={messagesEndRef} />
        </div>
      </ScrollArea>

      {/* Presence strip */}
      <PresenceStrip viewers={viewers} typing={typing} />

      {/* Smart reply chips */}
      {client && smartReplies.length > 0 && (
        <SmartReplyChips
          replies={smartReplies}
          conversationId={conversation.id}
          clientId={client.id}
          channel={conversation.channel === 'email' ? 'email' : 'sms'}
        />
      )}

      {/* Composer */}
      <Composer
        conversationId={conversation.id}
        clientId={client?.id ?? ''}
        channel={conversation.channel as 'sms' | 'email' | 'instagram' | 'whatsapp' | 'webchat' | 'phone'}
        clientFirstName={client?.first_name}
        clientHasPhone={!!client?.phone}
        clientHasEmail={!!client?.email}
        templates={templates}
        onOptimisticSend={handleOptimisticSend}
        onInternalNoteModeChange={() => void 0}
        disabled={!client}
      />

      {!client && (
        <p className="text-center text-xs text-[color:var(--color-stone)] px-4 py-1.5 bg-[color-mix(in_srgb,var(--color-stone)_8%,transparent)] border-t border-border">
          Link this conversation to a client before sending messages.
        </p>
      )}
    </div>
  )
}

'use client'

/**
 * ConversationList — 360px left panel listing conversations.
 *
 * Features:
 * - Search input (/ focus hotkey)
 * - Filter pills: All / Unread / Starred / Archived
 * - Realtime conversation list reconciliation
 * - Empty states (zero-state vs filter-zero)
 * - URL-driven state (?channel=, ?filter=, ?q=)
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { Search, Inbox, Star, Archive } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { cn } from '@/lib/utils'
import { useRealtimeConversationList } from '@/hooks/use-realtime-messages'
import { useDebounce } from '@/hooks/useDebounce'
import { ConversationListItem } from './ConversationListItem'
import { EmptyRail } from './EmptyRail'
import type { ConversationWithClient } from '@/lib/messaging/queries'
import type { Conversation } from '@/lib/supabase/types'

// ─── Filter pill config ────────────────────────────────────────────────────────

type FilterKey = 'all' | 'unread' | 'starred' | 'archived'

const FILTER_PILLS: { key: FilterKey; label: string; icon: React.ReactNode }[] = [
  { key: 'all', label: 'All', icon: <Inbox className="h-3 w-3" aria-hidden /> },
  { key: 'unread', label: 'Unread', icon: null },
  { key: 'starred', label: 'Starred', icon: <Star className="h-3 w-3" aria-hidden /> },
  { key: 'archived', label: 'Archived', icon: <Archive className="h-3 w-3" aria-hidden /> },
]

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getDisplayName(conv: ConversationWithClient): string {
  if (conv.display_name) return conv.display_name
  if (conv.client) {
    const { first_name, last_name } = conv.client
    return last_name ? `${first_name} ${last_name}` : first_name
  }
  return conv.external_identifier
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface ConversationListProps {
  conversations: ConversationWithClient[]
  studioId: string
  activeConversationId: string | null
}

// ─── ConversationList ─────────────────────────────────────────────────────────

export function ConversationList({
  conversations: initialConversations,
  studioId,
  activeConversationId,
}: ConversationListProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const searchInputRef = useRef<HTMLInputElement>(null)

  const currentFilter = (searchParams.get('filter') as FilterKey) ?? 'all'
  const currentChannel = searchParams.get('channel')

  const [convs, setConvs] = useState<ConversationWithClient[]>(initialConversations)
  const [searchRaw, setSearchRaw] = useState('')
  const search = useDebounce(searchRaw, 300)

  // Keep list in sync when server re-renders
  useEffect(() => {
    setConvs(initialConversations)
  }, [initialConversations])

  // Realtime reconciliation
  const handleConversationUpdate = useCallback((updated: Conversation) => {
    setConvs((prev) =>
      prev
        .map((c) => (c.id === updated.id ? { ...c, ...updated } : c))
        .sort((a, b) => {
          const aTime = a.last_message_at ?? a.created_at
          const bTime = b.last_message_at ?? b.created_at
          return new Date(bTime).getTime() - new Date(aTime).getTime()
        }),
    )
  }, [])

  useRealtimeConversationList(studioId, handleConversationUpdate)

  // Filter logic
  const filtered = convs.filter((c) => {
    // Status filter
    if (currentFilter === 'unread' && c.unread_count === 0) return false
    if (currentFilter === 'starred' && !c.starred) return false
    if (currentFilter === 'archived' && !c.archived_at) return false
    if (currentFilter !== 'archived' && c.archived_at) return false

    // Search
    if (search) {
      const q = search.toLowerCase()
      const name = getDisplayName(c).toLowerCase()
      const ext = c.external_identifier.toLowerCase()
      if (!name.includes(q) && !ext.includes(q)) return false
    }

    return true
  })

  function handleFilterChange(key: FilterKey) {
    const params = new URLSearchParams(searchParams.toString())
    if (key === 'all') {
      params.delete('filter')
    } else {
      params.set('filter', key)
    }
    router.push(`/messages?${params.toString()}`)
  }

  function handleClearFilter() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('filter')
    params.delete('channel')
    router.push(`/messages?${params.toString()}`)
  }

  function handleConversationClick(conv: ConversationWithClient) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('c', conv.id)
    router.push(`/messages?${params.toString()}`)
  }

  // Keyboard: / focuses search
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      const tag = (e.target as HTMLElement).tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA') {
        if (e.key === 'Escape') searchInputRef.current?.blur()
        return
      }
      if (e.key === '/') {
        e.preventDefault()
        searchInputRef.current?.focus()
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [])

  const isFiltered = currentFilter !== 'all' || !!currentChannel || !!search
  const hasAnyConversations = convs.length > 0

  return (
    <div className="w-[360px] shrink-0 flex flex-col h-full border-r border-border bg-background overflow-hidden">
      {/* Header */}
      <div className="px-4 pt-4 pb-3 shrink-0 border-b border-border">
        <h2 className="font-serif italic text-foreground text-base mb-3">Messages</h2>
        {/* Search */}
        <div className="relative">
          <Search
            className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[color:var(--color-stone)] pointer-events-none"
            aria-hidden
          />
          <Input
            ref={searchInputRef}
            placeholder="Search… (/)"
            value={searchRaw}
            onChange={(e) => setSearchRaw(e.target.value)}
            className="pl-8 h-8 text-sm"
            aria-label="Search conversations"
          />
        </div>
      </div>

      {/* Filter pills */}
      <div className="px-3 py-2 flex gap-1 shrink-0 border-b border-border">
        {FILTER_PILLS.map((pill) => {
          const isActive = currentFilter === pill.key
          return (
            <button
              key={pill.key}
              type="button"
              onClick={() => handleFilterChange(pill.key)}
              className={cn(
                'inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium transition-colors',
                isActive
                  ? 'bg-primary text-primary-foreground'
                  : 'text-[color:var(--color-stone)] hover:text-foreground hover:bg-[color-mix(in_srgb,var(--color-onyx)_6%,transparent)]',
              )}
              aria-pressed={isActive}
            >
              {pill.icon}
              {pill.label}
            </button>
          )
        })}
      </div>

      {/* Conversation list */}
      <ScrollArea className="flex-1 min-h-0">
        {!hasAnyConversations ? (
          <EmptyRail isFiltered={false} />
        ) : filtered.length === 0 ? (
          <EmptyRail isFiltered={isFiltered} onClearFilter={handleClearFilter} />
        ) : (
          <div role="listbox" aria-label="Conversations" className="py-1">
            {filtered.map((conv) => (
              <ConversationListItem
                key={conv.id}
                conv={conv}
                isActive={conv.id === activeConversationId}
                onClick={() => handleConversationClick(conv)}
              />
            ))}
          </div>
        )}
      </ScrollArea>
    </div>
  )
}

'use client'

/**
 * PresenceStrip — shows who is viewing or typing in the active conversation.
 * Always occupies min-h to prevent layout shift.
 * Typing animation: 3 Stone dots with staggered pulse.
 */

export interface PresenceUser {
  userId: string
  userName: string
  state: 'viewing' | 'typing'
}

interface PresenceStripProps {
  viewers: PresenceUser[]
  typing: PresenceUser[]
}

function formatNames(users: PresenceUser[]): string {
  const names = users.map((u) => u.userName)
  if (names.length === 0) return ''
  if (names.length === 1) return names[0] ?? ''
  if (names.length === 2) return `${names[0]} and ${names[1]}`
  return `${names[0]}, ${names[1]} and ${names.length - 2} more`
}

export function PresenceStrip({ viewers, typing }: PresenceStripProps) {
  const hasTyping = typing.length > 0
  const hasViewers = viewers.length > 0
  const hasAny = hasTyping || hasViewers

  return (
    <div className="px-4 py-1.5 min-h-[28px] flex items-center gap-2">
      {hasAny && (
        <p className="text-[13px] italic text-[color:var(--color-stone)] flex items-center gap-1.5">
          {hasTyping ? (
            <>
              <span>{formatNames(typing)} is typing</span>
              {/* 3-dot typing indicator */}
              <span className="flex items-center gap-0.5" aria-hidden>
                <span
                  className="w-1 h-1 rounded-full bg-[color:var(--color-stone)] animate-pulse"
                  style={{ animationDelay: '0ms' }}
                />
                <span
                  className="w-1 h-1 rounded-full bg-[color:var(--color-stone)] animate-pulse"
                  style={{ animationDelay: '200ms' }}
                />
                <span
                  className="w-1 h-1 rounded-full bg-[color:var(--color-stone)] animate-pulse"
                  style={{ animationDelay: '400ms' }}
                />
              </span>
            </>
          ) : hasViewers ? (
            <span>{formatNames(viewers)} is viewing</span>
          ) : null}
        </p>
      )}
    </div>
  )
}

