const isMobile = useIsMobile()
const isWide = useIsWide()
const isTablet = useIsTablet()
const router = useRouter()
const [, startTransition] = useTransition()

const [showContext, setShowContext] = useState(false)
const [showCheatsheet, setShowCheatsheet] = useState(false)

const currentChannel = searchParams.channel ?? null

// Navigate conversation list with j/k — move active conversation selection
const navigateList = useCallback((direction: 'down' | 'up') => {
  const listbox = document.querySelector<HTMLElement>('[role="listbox"][aria-label="Conversations"]')
  if (!listbox) return
  const items = Array.from(listbox.querySelectorAll<HTMLElement>('[role="option"]'))
  if (items.length === 0) return
  const currentIdx = items.findIndex((el) => el.getAttribute('aria-selected') === 'true')
  const nextIdx = direction === 'down'
    ? Math.min((currentIdx < 0 ? -1 : currentIdx) + 1, items.length - 1)
    : Math.max(currentIdx - 1, 0)
  items[nextIdx]?.click()
  items[nextIdx]?.scrollIntoView({ block: 'nearest' })
}, [])

useMessagesShortcuts({
  onFocusSearch: useCallback(() => {
    const el = document.querySelector<HTMLInputElement>('[aria-label="Search conversations"]')
    el?.focus()
  }, []),
  onNavigateDown: useCallback(() => navigateList('down'), [navigateList]),
  onNavigateUp: useCallback(() => navigateList('up'), [navigateList]),
  onFocusComposer: useCallback(() => {
    const el = document.querySelector<HTMLTextAreaElement>('[aria-label="Message body"]') ??
      document.querySelector<HTMLTextAreaElement>('[aria-label="Internal note body"]')
    el?.focus()
  }, []),
  onAssign: useCallback(() => {
    // Open assign popover on active thread — trigger click on Assign button
    const assignBtn = document.querySelector<HTMLButtonElement>('[aria-label="Assign conversation"]')
    assignBtn?.click()
  }, []),
  onArchive: useCallback(() => {
    if (!activeConversationId) return
    startTransition(async () => {
      const result = await archiveAction(activeConversationId)
      if (result.ok) {
        toast.success('Conversation archived')
        router.push('/messages')
      } else {
        toast.error(result.error ?? 'Failed to archive')
      }
    })
  }, [activeConversationId, router]),
  onStar: useCallback(() => {
    if (!activeConversationId || !activeConversation) return
    startTransition(async () => {
      const result = await starAction(activeConversationId, !activeConversation.starred)
      if (result.ok) {
        toast.success(activeConversation.starred ? 'Removed from starred' : 'Starred')
      } else {
        toast.error(result.error ?? 'Failed')
      }
    })
  }, [activeConversationId, activeConversation]),
  onToggleInternalNote: useCallback(() => {
    // Trigger click on the sticky-note button inside Composer
    const btn = document.querySelector<HTMLButtonElement>('[aria-label="Add staff note"], [aria-label="Exit staff note mode"]')
    btn?.click()
  }, []),
  onShowCheatsheet: useCallback(() => setShowCheatsheet(true), []),
  onClose: useCallback(() => setShowContext(false), []),
})

