import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { searchMessages } from '@/lib/messaging/queries'
import { logger } from '@/lib/logger'

const QuerySchema = z.object({
  q: z.string().min(3).max(100).trim(),
})

/**
 * GET /api/messages/search?q=...
 * Full-text search across message body + subject for the authenticated studio.
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = QuerySchema.safeParse({ q: searchParams.get('q') ?? '' })
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.issues[0]?.message ?? 'Query must be 3–100 characters' },
      { status: 400 },
    )
  }

  try {
    const messages = await searchMessages(authUser.studioId, parsed.data.q)
    return NextResponse.json({ data: messages })
  } catch (err) {
    logger.error({ err }, 'messages/search GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

