-- Studio channel mapping tables for omnichannel inbox (Sprint 2).
-- Maps Meta page_id / phone_number_id / widget_token → studio_id.
-- Run pnpm db:types after applying this migration to regenerate lib/supabase/types.ts.

-- ─── studio_instagram_pages ───────────────────────────────────────────────────
-- Maps Instagram page_id → studio_id for inbound DM routing.

CREATE TABLE IF NOT EXISTS studio_instagram_pages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id uuid NOT NULL REFERENCES studios(id) ON DELETE CASCADE,
  page_id text NOT NULL,
  page_name text,
  access_token text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (page_id)
);

ALTER TABLE studio_instagram_pages ENABLE ROW LEVEL SECURITY;

CREATE POLICY "studio_members_manage_instagram_pages"
  ON studio_instagram_pages
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM studio_members sm
      WHERE sm.studio_id = studio_instagram_pages.studio_id
        AND sm.user_id = auth.uid()
        AND sm.role IN ('owner', 'admin')
    )
  );

CREATE INDEX idx_studio_instagram_pages_page_id ON studio_instagram_pages(page_id);
CREATE INDEX idx_studio_instagram_pages_studio_id ON studio_instagram_pages(studio_id);

CREATE TRIGGER update_studio_instagram_pages_updated_at
  BEFORE UPDATE ON studio_instagram_pages
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ─── studio_whatsapp_numbers ──────────────────────────────────────────────────
-- Maps WhatsApp phone_number_id (Meta Business Cloud API) → studio_id.

CREATE TABLE IF NOT EXISTS studio_whatsapp_numbers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id uuid NOT NULL REFERENCES studios(id) ON DELETE CASCADE,
  phone_number_id text NOT NULL,
  display_number text,
  access_token text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (phone_number_id)
);

ALTER TABLE studio_whatsapp_numbers ENABLE ROW LEVEL SECURITY;

CREATE POLICY "studio_members_manage_whatsapp_numbers"
  ON studio_whatsapp_numbers
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM studio_members sm
      WHERE sm.studio_id = studio_whatsapp_numbers.studio_id
        AND sm.user_id = auth.uid()
        AND sm.role IN ('owner', 'admin')
    )
  );

CREATE INDEX idx_studio_whatsapp_numbers_phone_number_id ON studio_whatsapp_numbers(phone_number_id);
CREATE INDEX idx_studio_whatsapp_numbers_studio_id ON studio_whatsapp_numbers(studio_id);

CREATE TRIGGER update_studio_whatsapp_numbers_updated_at
  BEFORE UPDATE ON studio_whatsapp_numbers
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ─── studio_webchat_widgets ───────────────────────────────────────────────────
-- Maps widget_token (HMAC-verified in webhook) → studio_id.

CREATE TABLE IF NOT EXISTS studio_webchat_widgets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  studio_id uuid NOT NULL REFERENCES studios(id) ON DELETE CASCADE,
  widget_token text NOT NULL,
  widget_name text NOT NULL DEFAULT 'Web Chat',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (widget_token)
);

ALTER TABLE studio_webchat_widgets ENABLE ROW LEVEL SECURITY;

CREATE POLICY "studio_members_manage_webchat_widgets"
  ON studio_webchat_widgets
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM studio_members sm
      WHERE sm.studio_id = studio_webchat_widgets.studio_id
        AND sm.user_id = auth.uid()
        AND sm.role IN ('owner', 'admin')
    )
  );

CREATE INDEX idx_studio_webchat_widgets_token ON studio_webchat_widgets(widget_token);
CREATE INDEX idx_studio_webchat_widgets_studio_id ON studio_webchat_widgets(studio_id);

CREATE TRIGGER update_studio_webchat_widgets_updated_at
  BEFORE UPDATE ON studio_webchat_widgets
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ─── clients.instagram_psid ───────────────────────────────────────────────────
-- Stores the Meta Page-Scoped User ID for client matching on inbound IG DMs.

ALTER TABLE clients ADD COLUMN IF NOT EXISTS instagram_psid text;
CREATE INDEX IF NOT EXISTS idx_clients_instagram_psid ON clients(instagram_psid) WHERE instagram_psid IS NOT NULL;

