import { logger } from '@/lib/logger'
import { triageConversation, fireAutoReplyIfMatched } from '@/lib/messaging/triage'

// ─── Payload schema ───────────────────────────────────────────────────────────

const WebchatPayloadSchema = z.object({
  widget_token: z.string().min(1),
  sender_name: z.string().min(1).max(200),
  sender_email: z.string().email().optional(),
  body: z.string().min(1).max(4000),
  session_id: z.string().min(1).max(200),
})

// ─── Typed lookup helpers ─────────────────────────────────────────────────────

type ServiceClient = ReturnType<typeof createServiceRoleClient>

async function lookupStudioByWidgetToken(supabase: ServiceClient, widgetToken: string): Promise<string | null> {
  const { data } = await supabase
    .from('studio_webchat_widgets' as 'studios')
    .select('studio_id')
    .eq('widget_token' as 'name', widgetToken)
    .maybeSingle() as unknown as { data: { studio_id: string } | null }
  return data?.studio_id ?? null
}

async function lookupClientByEmail(supabase: ServiceClient, studioId: string, email: string): Promise<string | null> {
  const { data } = await supabase
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('email', email)
    .limit(1)
    .maybeSingle() as unknown as { data: { id: string } | null }
  return data?.id ?? null
}

