/**
 * Web chat widget webhook handler.
 *
 * POST only. Verifies HMAC-SHA256 in X-Webchat-Signature.
 * Routes widget_token → studio via studio_webchat_widgets table.
 * Matches client by sender_email.
 * Calls find_or_create_conversation RPC → inserts comm → triage → auto-reply.
 *
 * Expected payload:
 *   { widget_token, sender_name, sender_email?, body, session_id }
 *
 * Feature gate: omnichannel_inbox (Studio+).
 * Type note: studio_webchat_widgets uses rawDb() wrapper until pnpm db:types after migration.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { z } from 'zod'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { triageConversation, fireAutoReplyIfMatched } from '@/lib/messaging/triage'

// ─── Raw DB helper ────────────────────────────────────────────────────────────

type ServiceClient = ReturnType<typeof createServiceRoleClient>

type RawClient = {
  from(table: string): {
    select(cols: string): {
      eq(col: string, val: string): {
        limit(n: number): { maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }> }
        maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }>
        single(): Promise<{ data: Record<string, string> | null; error: unknown }>
      }
    }
    insert(row: Record<string, unknown>): {
      select(cols: string): {
        single(): Promise<{ data: Record<string, string> | null; error: unknown }>
      }
    }
  }
  rpc(fn: string, args: Record<string, string | null>): Promise<{ data: unknown; error: unknown }>
}

function rawDb(supabase: ServiceClient): RawClient {
  return supabase as unknown as RawClient
}

// ─── Payload schema ───────────────────────────────────────────────────────────

const PayloadSchema = z.object({
  widget_token: z.string().min(1).max(200),
  sender_name: z.string().min(1).max(200),
  sender_email: z.string().email().optional(),
  body: z.string().min(1).max(4000),
  session_id: z.string().min(1).max(200),
})

// ─── POST — Inbound web chat message ─────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(`webchat:${ip}`)
  if (!rl.success) return new NextResponse('Too many requests', { status: 429 })

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  const secret = process.env.WEBCHAT_WEBHOOK_SECRET
  if (!secret) {
    logger.error({}, 'webchat-webhook: WEBCHAT_WEBHOOK_SECRET not set')
    return new NextResponse(JSON.stringify({ error: 'Webhook not configured' }), {
      status: 503, headers: { 'Content-Type': 'application/json' },
    })
  }

  const signature = request.headers.get('x-webchat-signature') ?? ''
  const sigBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expected = createHmac('sha256', secret).update(rawBody).digest()

  if (sigBuffer.length !== expected.length || !timingSafeEqual(sigBuffer, expected)) {
    logger.warn({}, 'webchat-webhook: invalid X-Webchat-Signature')
    return new NextResponse('Forbidden', { status: 403 })
  }

  let payload: z.infer<typeof PayloadSchema>
  try {
    const json = JSON.parse(rawBody) as unknown
    const result = PayloadSchema.safeParse(json)
    if (!result.success) {
      logger.warn({ issues: result.error.issues }, 'webchat-webhook: invalid payload')
      return new NextResponse('Bad request', { status: 400 })
    }
    payload = result.data
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  const supabase = createServiceRoleClient()

  try {
    await handleInboundMessage(supabase, payload)
  } catch (err) {
    logger.error({ err, sessionId: payload.session_id }, 'webchat-webhook: ingest error')
  }

  return new NextResponse(null, { status: 200 })
}

// ─── handleInboundMessage ─────────────────────────────────────────────────────

async function handleInboundMessage(
  supabase: ServiceClient,
  msg: z.infer<typeof PayloadSchema>,
): Promise<void> {
  const db = rawDb(supabase)

  // 1. Resolve studio from widget_token
  const { data: widgetRow } = await db
    .from('studio_webchat_widgets')
    .select('studio_id')
    .eq('widget_token', msg.widget_token)
    .maybeSingle()
  const studioId = widgetRow?.studio_id ?? null
  if (!studioId) {
    logger.warn({}, 'webchat-webhook: no studio mapped to widget_token — dropped')
    return
  }

  // 2. Match client by email (if provided)
  let clientId: string | null = null
  if (msg.sender_email) {
    const { data: clientRow } = await db
      .from('clients')
      .select('id')
      .eq('studio_id', studioId)
      .eq('email', msg.sender_email)
      .limit(1)
      .maybeSingle()
