})

// ─── Typed lookup helpers ─────────────────────────────────────────────────────

type ServiceClient = ReturnType<typeof createServiceRoleClient>

async function lookupStudioByWidgetToken(supabase: ServiceClient, widgetToken: string): Promise<string | null> {
  const { data } = await supabase
    .from('studio_webchat_widgets' as 'studios')
    .select('studio_id')
    .eq('widget_token' as 'name', widgetToken)
    .maybeSingle() as unknown as { data: { studio_id: string } | null }
  return data?.studio_id ?? null
}

async function lookupClientByEmail(supabase: ServiceClient, studioId: string, email: string): Promise<string | null> {
  const { data } = await supabase
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('email', email)
    .limit(1)
    .maybeSingle() as unknown as { data: { id: string } | null }
  return data?.id ?? null
}

async function findOrCreateConversation(
  supabase: ServiceClient,
  studioId: string,
  channel: string,
  externalIdentifier: string,
  clientId: string | null,
): Promise<string | null> {
  const args: Record<string, string | null> = {
    p_studio_id: studioId,
    p_channel: channel,
    p_external_identifier: externalIdentifier,
    p_client_id: clientId,
  }
  const { data, error } = await supabase.rpc(
    'find_or_create_conversation' as 'accept_team_invite',
    args as unknown as Parameters<typeof supabase.rpc>[1],
  )
  if (error) {
    logger.error({ err: error }, 'webchat-webhook: find_or_create_conversation RPC failed')
    return null
  }
  return data as unknown as string
}

// ─── POST — Inbound web chat message ─────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(`webchat:${ip}`)
  if (!rl.success) {
    return new NextResponse('Too many requests', { status: 429 })
  }

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  // Verify X-Webchat-Signature
  const secret = process.env.WEBCHAT_WEBHOOK_SECRET
  if (!secret) {
    logger.error({}, 'webchat-webhook: WEBCHAT_WEBHOOK_SECRET not set — rejecting')
    return new NextResponse(JSON.stringify({ error: 'Webhook not configured' }), {
      status: 503,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const signature = request.headers.get('x-webchat-signature') ?? ''
  const sigBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expected = createHmac('sha256', secret).update(rawBody).digest()

  if (sigBuffer.length !== expected.length || !timingSafeEqual(sigBuffer, expected)) {
    logger.warn({}, 'webchat-webhook: invalid X-Webchat-Signature')
    return new NextResponse('Forbidden', { status: 403 })
  }

  let parsed: z.infer<typeof WebchatPayloadSchema>
  try {
    const json = JSON.parse(rawBody) as unknown
    const result = WebchatPayloadSchema.safeParse(json)
    if (!result.success) {
      logger.warn({ issues: result.error.issues }, 'webchat-webhook: invalid payload schema')
      return new NextResponse('Bad request', { status: 400 })
    }
    parsed = result.data
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  const supabase = createServiceRoleClient()

  try {
    await handleInboundMessage(supabase, parsed)
  } catch (err) {
    logger.error({ err, sessionId: parsed.session_id }, 'webchat-webhook: ingest error (non-fatal)')
  }

  return new NextResponse(null, { status: 200 })
}

// ─── handleInboundMessage ─────────────────────────────────────────────────────

async function handleInboundMessage(
  supabase: ServiceClient,
  msg: z.infer<typeof WebchatPayloadSchema>,
): Promise<void> {
  // 1. Resolve studio from widget_token
  const studioId = await lookupStudioByWidgetToken(supabase, msg.widget_token)
  if (!studioId) {
    logger.warn({ widgetToken: '[REDACTED]' }, 'webchat-webhook: no studio mapped to widget_token — dropped')
    return
  }

  // 2. Match client by email (if provided)
  const clientId = msg.sender_email
    ? await lookupClientByEmail(supabase, studioId, msg.sender_email)
    : null

  // 3. Find or create conversation (keyed on session_id for continuity)
  const conversationId = await findOrCreateConversation(supabase, studioId, 'webchat', msg.session_id, clientId)
  if (!conversationId) return

  // 4. Skip insert if no client
  if (!clientId) {
    logger.warn({ sessionId: msg.session_id, studioId, conversationId }, 'webchat-webhook: unknown sender — conv created but comm not stored')
    return
  }

  // 5. Insert inbound comm
  const { data: insertedComm, error: insertError } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      conversation_id: conversationId,
      channel: 'webchat' as 'sms',
      direction: 'inbound',
      body: msg.body,
      status: 'delivered',
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      provider_message_id: `webchat:${msg.session_id}:${Date.now()}`,
      metadata: {
        sender_name: msg.sender_name,
        sender_email: msg.sender_email,
        session_id: msg.session_id,
      } as Record<string, unknown>,
    })
    .select('id')
    .single()

  if (insertError || !insertedComm) {
    logger.error({ err: insertError, sessionId: msg.session_id }, 'webchat-webhook: comm insert failed')
    return
  }

  logger.info({ sessionId: msg.session_id, studioId, conversationId }, 'webchat-webhook: inbound message stored')

  // 6. Triage + auto-reply (non-fatal)
  try {
    await triageConversation(studioId, conversationId)
  } catch (err) {
    logger.error({ err, conversationId }, 'webchat-webhook: triage failed (non-fatal)')
  }

  const commId = (insertedComm as unknown as { id: string }).id
  try {
    await fireAutoReplyIfMatched(studioId, conversationId, commId)
  } catch (err) {
    logger.error({ err, conversationId }, 'webchat-webhook: auto-reply failed (non-fatal)')
  }
}

