'use client'

/**
 * Message attachment upload helper.
 *
 * Uploads files to the `message-attachments` Supabase Storage bucket.
 * Bucket must exist and have studio-member RLS policy.
 * Path: {studio_id}/{conversation_id}/{timestamp}-{sanitized_filename}
 *
 * Bucket creation (run once via Supabase dashboard or migration):
 *   INSERT INTO storage.buckets (id, name, public) VALUES ('message-attachments', 'message-attachments', false);
 */

import { createClient } from '@/lib/supabase/client'

const BUCKET = 'message-attachments'
const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024 // 10 MB
const MAX_FILES = 5
const ALLOWED_TYPES = [
  'image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/heic',
  'application/pdf',
]

export interface AttachmentUploadContext {
  studioId: string
  conversationId: string
}

export interface UploadedAttachment {
  url: string
  filename: string
  mime_type: string
  size_bytes: number
}

export type AttachmentValidationError =
  | { kind: 'too_many_files'; max: number }
  | { kind: 'file_too_large'; filename: string; maxMb: number }
  | { kind: 'unsupported_type'; filename: string; mime_type: string }

export function validateFiles(files: File[]): AttachmentValidationError | null {
  if (files.length > MAX_FILES) {
    return { kind: 'too_many_files', max: MAX_FILES }
  }
  for (const file of files) {
    if (file.size > MAX_FILE_SIZE_BYTES) {
      return { kind: 'file_too_large', filename: file.name, maxMb: 10 }
    }
    if (!ALLOWED_TYPES.includes(file.type)) {
      return { kind: 'unsupported_type', filename: file.name, mime_type: file.type }
    }
  }
  return null
}

export function validationErrorMessage(err: AttachmentValidationError): string {
  switch (err.kind) {
    case 'too_many_files': return `Maximum ${err.max} files per message.`
    case 'file_too_large': return `"${err.filename}" exceeds the 10 MB limit.`
    case 'unsupported_type': return `"${err.filename}" is not a supported file type.`
  }
}

export async function uploadMessageAttachment(
  file: File,
  ctx: AttachmentUploadContext,
): Promise<UploadedAttachment> {
  const supabase = createClient()

  // Sanitize filename: remove special chars, preserve extension
  const ext = file.name.split('.').pop() ?? ''
  const safeName = file.name
    .replace(/[^a-zA-Z0-9._-]/g, '-')
    .replace(/-+/g, '-')
    .toLowerCase()
  const uniqueName = `${Date.now()}-${safeName || `file.${ext}`}`
  const path = `${ctx.studioId}/${ctx.conversationId}/${uniqueName}`

  const { error: uploadError } = await supabase.storage
    .from(BUCKET)
    .upload(path, file, {
      contentType: file.type,
      upsert: false,
    })

  if (uploadError) {
    throw new Error(`Upload failed: ${uploadError.message}`)
  }

  const { data: urlData } = supabase.storage.from(BUCKET).getPublicUrl(path)

  return {
    url: urlData.publicUrl,
    filename: file.name,
    mime_type: file.type,
    size_bytes: file.size,
  }
}

