    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: params.clientId,
      conversation_id: params.conversationId,
      channel: 'in_app',
      direction: 'outbound',
      body: params.body,
      status: 'delivered',
      is_internal_note: true,
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      metadata: {},
    })
    .select('id')
    .single()

  if (error || !comm) {
    logger.error({ err: error, studioId }, 'messaging: sendInternalNote failed to insert')
    return { ok: false, error: 'Failed to save internal note' }
  }

  return { ok: true, commId: comm.id }
}

