import { format } from 'date-fns'
import { Clock, Check, CheckCheck, AlertCircle, Paperclip } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { ConversationMessage } from '@/lib/messaging/queries'

// ─── Media preview ─────────────────────────────────────────────────────────────

interface AttachmentPreview {
  url: string
  filename: string
  mime_type: string
}

function parseAttachments(msg: ConversationMessage): AttachmentPreview[] {
  const meta = msg.metadata as Record<string, unknown> | null
  if (!meta) return []

  const attachments: AttachmentPreview[] = []

  // Uploaded attachments ({ url, filename, mime_type }[])
  if (Array.isArray(meta['attachments'])) {
    for (const a of meta['attachments'] as unknown[]) {
      if (
        typeof a === 'object' && a !== null &&
        'url' in a && typeof (a as Record<string, unknown>)['url'] === 'string'
      ) {
        const att = a as Record<string, unknown>
        attachments.push({
          url: att['url'] as string,
          filename: (att['filename'] as string | undefined) ?? 'attachment',
          mime_type: (att['mime_type'] as string | undefined) ?? 'application/octet-stream',
        })
      }
    }
  }

  // Twilio MMS media_urls (string[])
  if (Array.isArray(meta['media_urls'])) {
    for (const url of meta['media_urls'] as unknown[]) {
      if (typeof url === 'string') {
        attachments.push({ url, filename: 'media', mime_type: 'image/jpeg' })
      }
    }
  }

  return attachments
}

function AttachmentsRow({ attachments }: { attachments: AttachmentPreview[] }) {
  if (attachments.length === 0) return null
  return (
    <div className="flex flex-wrap gap-1.5 mt-1.5">
      {attachments.map((att) => {
        const isImage = att.mime_type.startsWith('image/')
        if (isImage) {
          return (
            <a
              key={att.url}
              href={att.url}
              target="_blank"
              rel="noopener noreferrer"
              className="block rounded-md overflow-hidden border border-border hover:opacity-90 transition-opacity"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={att.url}
                alt={att.filename}
                className="max-h-48 max-w-[220px] object-cover"
                loading="lazy"
              />
            </a>
          )
        }
        return (
          <a
            key={att.url}
            href={att.url}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-1.5 px-2.5 py-1.5 text-xs rounded-md border border-border bg-background hover:bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)] transition-colors"
          >
            <Paperclip className="h-3 w-3 shrink-0 text-[color:var(--color-stone)]" aria-hidden />
            <span className="truncate max-w-[140px]">{att.filename}</span>
          </a>
        )
      })}
    </div>
  )
}

