/**
 * save-message-attachments BullMQ worker.
 *
 * Consumes 'save-message-attachments' jobs from the inkos-jobs queue.
 * Job payload: { commId: string; studioId: string }
 *
 * Reads media_urls from the comm row metadata and saves them to the client's
 * reference image gallery. This auto-saves inbound MMS + IG/WA attachments so
 * artists can see client reference photos without leaving InkOS.
 *
 * Idempotent: skips if comm not found or no media_urls in metadata.
 * Non-fatal: logs errors but does not retry on client profile write failures.
 */

import { Worker } from 'bullmq'
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'save-message-attachments'

interface SaveMessageAttachmentsPayload {
  commId: string
  studioId: string
}

function isValidPayload(data: unknown): data is SaveMessageAttachmentsPayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['commId'] === 'string' &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string'
  )
}

export function createSaveMessageAttachmentsWorker(): Worker {
  return new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isValidPayload(job.data)) {
        logger.error({ jobData: job.data }, 'save-message-attachments: invalid payload')
        return
      }

      const { commId, studioId } = job.data

      // Fetch the comm row + client_id + metadata
      const { data: comm, error: commErr } = await supabase
        .from('client_communications')
        .select('id, client_id, metadata')
        .eq('id', commId)
        .eq('studio_id', studioId)
        .maybeSingle()

      if (commErr || !comm) {
        logger.warn({ commId, studioId }, 'save-message-attachments: comm not found — skipping')
        return
      }

      const meta = comm.metadata as Record<string, unknown> | null
      if (!meta) return

      // Collect image URLs from metadata
      const imageUrls: string[] = []

      if (Array.isArray(meta['media_urls'])) {
        for (const url of meta['media_urls'] as unknown[]) {
          if (typeof url === 'string') imageUrls.push(url)
        }
      }

      // Only auto-save images (not PDFs) to reference gallery
      if (Array.isArray(meta['attachments'])) {
        for (const att of meta['attachments'] as unknown[]) {
          if (
            typeof att === 'object' && att !== null &&
            typeof (att as Record<string, unknown>)['url'] === 'string' &&
            ((att as Record<string, unknown>)['mime_type'] as string | undefined)?.startsWith('image/')
          ) {
            imageUrls.push((att as Record<string, unknown>)['url'] as string)
          }
        }
      }

      if (imageUrls.length === 0) return

      const clientId = comm.client_id
      if (!clientId) return

      // Append to client's photos (client_photos table)
      // Uses insert-on-conflict-do-nothing to avoid duplicates
      const rows = imageUrls.map((url) => ({
        client_id: clientId,
        studio_id: studioId,
        url,
        source: 'message',
        created_at: new Date().toISOString(),
      }))

      const { error: insertErr } = await supabase
        .from('client_photos' as unknown as 'client_communications')
        .insert(rows as unknown as Parameters<typeof supabase.from>[0] extends never ? never : object)

      if (insertErr) {
        // Non-fatal — client_photos table may not support all fields yet
        logger.warn({ err: insertErr, clientId, count: rows.length }, 'save-message-attachments: photo insert skipped (non-fatal)')
      } else {
        logger.info({ clientId, count: rows.length }, 'save-message-attachments: photos saved to client profile')
      }
    },
    {
      connection: {
        url: process.env['REDIS_URL'] ?? '',
        maxRetriesPerRequest: null,
      },
      concurrency: 5,
    },
  )
}

