/**
 * Resend inbound email webhook handler.
 *
 * POST only. Verifies HMAC-SHA256 signature in Resend-Signature header.
 * Parses inbound email, routes to studio, matches client by from-email,
 * then calls find_or_create_conversation → inserts comm → triage → auto-reply.
 *
 * Studio routing:
 *   v1: Falls back to RESEND_INBOUND_DEFAULT_STUDIO_ID env var (single-studio setup).
 *   v2: Add studio_email_inboxes table mapping inbound addresses → studio_id.
 *
 * Configure in Resend dashboard:
 *   Settings → Inbound → Add webhook URL: {NEXT_PUBLIC_APP_URL}/api/webhooks/resend-inbound
 *
 * Required env vars:
 *   RESEND_WEBHOOK_SECRET — signing secret from Resend dashboard
 *   RESEND_INBOUND_DEFAULT_STUDIO_ID — fallback studio for v1 routing
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { z } from 'zod'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { triageConversation, fireAutoReplyIfMatched } from '@/lib/messaging/triage'

// ─── Raw DB helper ────────────────────────────────────────────────────────────

type ServiceClient = ReturnType<typeof createServiceRoleClient>

type RawChain = {
  eq(col: string, val: string): RawChain
  limit(n: number): { maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }> }
  maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }>
  single(): Promise<{ data: Record<string, string> | null; error: unknown }>
}

type RawClient = {
  from(table: string): {
    select(cols: string): RawChain
    insert(row: Record<string, unknown>): {
      select(cols: string): {
        single(): Promise<{ data: Record<string, string> | null; error: unknown }>
      }
    }
  }
  rpc(fn: string, args: Record<string, string | null>): Promise<{ data: unknown; error: unknown }>
}

function rawDb(supabase: ServiceClient): RawClient {
  return supabase as unknown as RawClient
}

// ─── Resend inbound payload schema ───────────────────────────────────────────

const ResendInboundSchema = z.object({
  from: z.string().min(1),
  to: z.union([z.string(), z.array(z.string())]).transform((v) =>
    Array.isArray(v) ? v[0] ?? '' : v,
  ),
  subject: z.string().optional().default('(no subject)'),
  text: z.string().optional().default(''),
  html: z.string().optional(),
  headers: z.record(z.string()).optional(),
})

// Strip display name from "John Smith <john@example.com>" format
function extractEmail(raw: string): string {
  const match = /<([^>]+)>/.exec(raw)
  return match?.[1]?.trim() ?? raw.trim()
}

// ─── POST — Inbound email ─────────────────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(`resend-inbound:${ip}`)
  if (!rl.success) return new NextResponse('Too many requests', { status: 429 })

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  // Verify Resend-Signature (HMAC-SHA256)
  const webhookSecret = process.env.RESEND_WEBHOOK_SECRET
  if (!webhookSecret) {
    logger.error({}, 'resend-inbound: RESEND_WEBHOOK_SECRET not set')
    return new NextResponse(JSON.stringify({ error: 'Webhook not configured' }), {
      status: 503, headers: { 'Content-Type': 'application/json' },
    })
  }

  const signature = request.headers.get('resend-signature') ?? ''
  const sigBuffer = Buffer.from(signature, 'hex')
  const expected = createHmac('sha256', webhookSecret).update(rawBody).digest()

  if (sigBuffer.length !== expected.length || !timingSafeEqual(sigBuffer, expected)) {
    logger.warn({}, 'resend-inbound: invalid Resend-Signature')
    return new NextResponse('Forbidden', { status: 403 })
  }

  let payload: z.infer<typeof ResendInboundSchema>
  try {
    const json = JSON.parse(rawBody) as unknown
    const result = ResendInboundSchema.safeParse(json)
    if (!result.success) {
      logger.warn({ issues: result.error.issues }, 'resend-inbound: invalid payload')
      return new NextResponse('Bad request', { status: 400 })
    }
    payload = result.data
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  const supabase = createServiceRoleClient()

  try {
    await handleInboundEmail(supabase, payload)
  } catch (err) {
    logger.error({ err, from: payload.from }, 'resend-inbound: ingest error')
  }

  return new NextResponse(null, { status: 200 })
}

// ─── handleInboundEmail ───────────────────────────────────────────────────────

async function handleInboundEmail(
  supabase: ServiceClient,
  msg: z.infer<typeof ResendInboundSchema>,
): Promise<void> {
  const db = rawDb(supabase)
  const fromEmail = extractEmail(msg.from)

  // 1. Resolve studio
  // v1: use fallback env var. v2 would look up studio_email_inboxes by `to` address.
  const studioId = process.env.RESEND_INBOUND_DEFAULT_STUDIO_ID ?? null
  if (!studioId) {
    logger.warn({ to: msg.to }, 'resend-inbound: RESEND_INBOUND_DEFAULT_STUDIO_ID not set — dropped')
    return
  }

  // 2. Match client by from email
  const { data: clientRow } = await db
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('email', fromEmail)
    .limit(1)
    .maybeSingle()
  const clientId = clientRow?.id ?? null

  // 3. Find or create conversation (keyed on from-email for email threads)
  const { data: convData, error: rpcError } = await db.rpc('find_or_create_conversation', {
    p_studio_id: studioId,
    p_channel: 'email',
    p_external_identifier: fromEmail,
    p_client_id: clientId,
  })
  if (rpcError || !convData) {
    logger.error({ err: rpcError, fromEmail, studioId }, 'resend-inbound: find_or_create_conversation failed')
    return
  }
  const conversationId = convData as string

  // 4. Skip insert if no client
  if (!clientId) {
    logger.warn({ fromEmail, studioId }, 'resend-inbound: unknown sender — comm not stored')
    return
  }

  const body = msg.text.trim() || msg.subject

  // 5. Insert inbound comm
  const { data: insertedComm, error: insertError } = await db
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      conversation_id: conversationId,
      channel: 'email',
      direction: 'inbound',
      subject: msg.subject,
      body,
      status: 'delivered',
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      metadata: { from_email: fromEmail, to_email: msg.to },
    })
    .select('id')
    .single()

  if (insertError || !insertedComm) {
    logger.error({ err: insertError, fromEmail }, 'resend-inbound: comm insert failed')
    return
  }

  logger.info({ fromEmail, studioId, conversationId }, 'resend-inbound: email stored')

  // 6. Triage + auto-reply (non-fatal)
  try { await triageConversation(studioId, conversationId) }
  catch (err) { logger.error({ err, conversationId }, 'resend-inbound: triage failed (non-fatal)') }

  const commId = insertedComm.id
  if (commId) {
    try { await fireAutoReplyIfMatched(studioId, conversationId, commId) }
    catch (err) { logger.error({ err, conversationId }, 'resend-inbound: auto-reply failed (non-fatal)') }
  }
}

