  const handleToggleClient = useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const handleSend = useCallback(() => {
    const ids = selectedIds.size > 0 ? [...selectedIds] : reachable.map((c) => c.id)
    if (ids.length === 0) { toast.error('No recipients with a valid contact.'); return }
    if (!body.trim()) { toast.error('Message body is required.'); return }

    startTransition(async () => {
      const result = await massBlastAction({
        clientIds: ids,
        channel,
        body: body.trim(),
        ...(channel === 'email' && subject.trim() ? { subject: subject.trim() } : {}),
      })
      if (result.ok) {
        toast.success(`Blast queued for ${ids.length} client${ids.length !== 1 ? 's' : ''}`)
        onOpenChange(false)
        setStep('audience')
        setSelectedIds(new Set())
        setBody('')
        setSubject('')
      } else {
        toast.error(result.error ?? 'Failed to send blast')
      }
    })
  }, [selectedIds, reachable, channel, body, subject, onOpenChange])

  const selectedCount = selectedIds.size > 0 ? selectedIds.size : reachable.length
  const canProceed = body.trim().length > 0

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-[480px] sm:max-w-[480px] flex flex-col h-full p-0" side="right">
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border">
          <SheetTitle className="font-serif italic text-xl">Mass message</SheetTitle>
          {/* Step indicator */}
          <div className="flex items-center gap-2 pt-1">
            {(['audience', 'compose', 'review'] as Step[]).map((s, i) => (
              <div key={s} className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => {
                    if (s === 'compose' && step === 'review') setStep('compose')
                    if (s === 'audience') setStep('audience')
                  }}
                  className={cn(
                    'text-xs font-medium capitalize',
                    step === s ? 'text-foreground' : 'text-[color:var(--color-stone)]',
                  )}
                >
                  {i + 1}. {s}
                </button>
                {i < 2 && <ChevronRight className="h-3 w-3 text-[color:var(--color-stone)]" aria-hidden />}
              </div>
            ))}
          </div>
        </SheetHeader>

        <div className="flex-1 min-h-0 overflow-y-auto px-6 py-4">
          {/* ── Step 1: Audience ──────────────────────────────────────────────── */}
          {step === 'audience' && (
            <div className="space-y-4">
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-2">
                  Filter by tag
                </p>
                <div className="flex flex-wrap gap-1.5">
                  <button
                    type="button"
                    onClick={() => setTagFilter(null)}
                    className={cn(
                      'px-2.5 py-1 rounded-full text-xs font-medium transition-colors',
                      !tagFilter
                        ? 'bg-primary text-primary-foreground'
                        : 'border border-border text-[color:var(--color-stone)] hover:text-foreground',
                    )}
                  >
                    All clients
                  </button>
                  {tagLibrary.map((tag) => (
                    <button
                      key={tag.id}
                      type="button"
                      onClick={() => setTagFilter(tagFilter === tag.name ? null : tag.name)}
                      className={cn(
                        'px-2.5 py-1 rounded-full text-xs font-medium transition-colors',
                        tagFilter === tag.name
                          ? 'bg-primary text-primary-foreground'
                          : 'border border-border text-[color:var(--color-stone)] hover:text-foreground',
                      )}
                    >
                      {tag.name}
                    </button>
                  ))}
                </div>
              </div>

              <Separator />

              <div>
                <div className="flex items-center justify-between mb-2">
                  <p className="text-xs font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
                    Recipients ({reachable.length} reachable via {channel})
                  </p>
                  <button
                    type="button"
                    onClick={handleSelectAll}
                    className="text-xs text-[color:var(--color-stone)] hover:text-foreground"
                  >
                    {selectedIds.size === reachable.length ? 'Deselect all' : 'Select all'}
                  </button>
                </div>
                <div className="space-y-1 max-h-[300px] overflow-y-auto">
                  {filteredClients.map((c) => {
                    const hasContact = channel === 'sms' ? !!c.phone : !!c.email
                    const isSelected = selectedIds.has(c.id) || selectedIds.size === 0
                    const name = [c.first_name, c.last_name].filter(Boolean).join(' ')
                    return (
                      <button
                        key={c.id}
                        type="button"
                        disabled={!hasContact}
                        onClick={() => handleToggleClient(c.id)}
                        className={cn(
                          'w-full flex items-center gap-2 px-2 py-1.5 rounded-md text-left text-sm transition-colors',
                          !hasContact && 'opacity-40 cursor-not-allowed',
                          hasContact && isSelected && 'bg-[color-mix(in_srgb,var(--color-onyx)_5%,transparent)]',
                          hasContact && !isSelected && 'hover:bg-[color-mix(in_srgb,var(--color-onyx)_4%,transparent)]',
                        )}
                      >
                        <span className="flex-1 truncate">{name}</span>
                        <span className="text-[11px] text-[color:var(--color-stone)] truncate max-w-[140px]">
                          {channel === 'sms' ? c.phone : c.email}
                        </span>
                      </button>
                    )
                  })}
                </div>
              </div>
            </div>
          )}

          {/* ── Step 2: Compose ───────────────────────────────────────────────── */}
          {step === 'compose' && (
            <div className="space-y-4">
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-2">
                  Channel
                </p>
                <div className="flex gap-2">
                  {(['sms', 'email'] as BlastChannel[]).map((ch) => (
                    <button
                      key={ch}
                      type="button"
                      onClick={() => setChannel(ch)}
                      className={cn(
                        'flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium border transition-colors',
                        channel === ch
                          ? 'border-primary bg-[color-mix(in_srgb,var(--color-onyx)_8%,transparent)] text-foreground'
                          : 'border-border text-[color:var(--color-stone)] hover:text-foreground',
                      )}
                    >
                      {ch === 'sms'
                        ? <MessageSquare className="h-3.5 w-3.5" aria-hidden />
                        : <Mail className="h-3.5 w-3.5" aria-hidden />}
                      {ch.toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>

              {channel === 'email' && (
                <div>
                  <p className="text-xs font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-1.5">
                    Subject
                  </p>
                  <input
                    type="text"
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                    placeholder="Email subject…"
                    maxLength={200}
                    className="w-full h-9 px-3 text-sm border border-border rounded-md bg-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  />
                </div>
              )}

              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <p className="text-xs font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
                    Message body
                  </p>
                  {channel === 'sms' && (
                    <span className={cn('text-[11px]', body.length > 160 ? 'text-[color:var(--color-rust)]' : 'text-[color:var(--color-stone)]')}>
                      {body.length}/160
                      {body.length > 160 && ` (${Math.ceil(body.length / 160)} segments)`}
                    </span>
                  )}
                </div>
                <Textarea
                  value={body}
                  onChange={(e) => setBody(e.target.value)}
                  placeholder={`Type your ${channel === 'sms' ? 'SMS message' : 'email body'}… You can use {{first_name}} as a placeholder.`}
                  rows={6}
                  maxLength={channel === 'sms' ? 1000 : 4000}
                  className="resize-none text-sm"
                />
              </div>

              {/* Live preview */}
              {body.trim() && (
                <div className="rounded-md border border-border/60 bg-[color-mix(in_srgb,var(--color-onyx)_3%,transparent)] p-3">
                  <p className="text-[10px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-1.5">Preview</p>
                  <p className="text-sm text-foreground whitespace-pre-wrap">
                    {body.replace(/\{\{first_name\}\}/g, 'Alex')}
                  </p>
                </div>
              )}
            </div>
          )}

          {/* ── Step 3: Review ────────────────────────────────────────────────── */}
          {step === 'review' && (
            <div className="space-y-4">
              <div className="rounded-md border border-border p-4 space-y-3">
                <div className="flex items-center gap-2">
                  <Users className="h-4 w-4 text-[color:var(--color-stone)]" aria-hidden />
                  <span className="text-sm font-medium">
                    {selectedCount} recipient{selectedCount !== 1 ? 's' : ''}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  {channel === 'sms'
                    ? <MessageSquare className="h-4 w-4 text-[color:var(--color-stone)]" aria-hidden />
                    : <Mail className="h-4 w-4 text-[color:var(--color-stone)]" aria-hidden />}
                  <span className="text-sm text-[color:var(--color-stone)]">{channel.toUpperCase()}</span>
                </div>
                {channel === 'email' && subject && (
                  <p className="text-xs text-[color:var(--color-stone)]">Subject: {subject}</p>
                )}
              </div>

              <div>
                <p className="text-xs font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)] mb-2">Message</p>
                <div className="rounded-md border border-border p-3 bg-[color-mix(in_srgb,var(--color-onyx)_3%,transparent)]">
                  <p className="text-sm text-foreground whitespace-pre-wrap">{body}</p>
                </div>
              </div>

              <p className="text-xs text-[color:var(--color-stone)]">
                This will send immediately. All recipients will receive the same message.
              </p>
            </div>
          )}
        </div>

        {/* Footer actions */}
        <div className="px-6 py-4 border-t border-border flex items-center justify-between gap-3 bg-background shrink-0">
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              if (step === 'audience') onOpenChange(false)
              else if (step === 'compose') setStep('audience')
              else if (step === 'review') setStep('compose')
            }}
          >
            <ChevronLeft className="h-3.5 w-3.5 mr-1" aria-hidden />
            {step === 'audience' ? 'Cancel' : 'Back'}
          </Button>

          {step !== 'review' ? (
            <Button
              size="sm"
              disabled={step === 'compose' && !canProceed}
              onClick={() => {
                if (step === 'audience') setStep('compose')
                else if (step === 'compose') setStep('review')
              }}
            >
              Next
              <ChevronRight className="h-3.5 w-3.5 ml-1" aria-hidden />
            </Button>
          ) : (
            <Button
              size="sm"
              disabled={isPending || selectedCount === 0}
              onClick={handleSend}
            >
              {isPending
                ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" aria-hidden />Sending…</>
                : <><Send className="h-3.5 w-3.5 mr-1.5" aria-hidden />Send to {selectedCount}</>}
            </Button>
          )}
        </div>
      </SheetContent>
    </Sheet>
  )
}

