const MassBlastSchema = z.object({
  clientIds: z.array(z.string().uuid()).min(1).max(500),
  channel: z.enum(['sms', 'email']),
  body: z.string().min(1).max(1000),
  subject: z.string().max(200).optional(),
})

export async function massBlastAction(
  input: z.infer<typeof MassBlastSchema>,
): Promise<ActionResult<{ queued: number }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  // Require marketing_advanced feature gate (Studio+)
  try {
    const supabase = await createClient()
    await requireFeatureRpc(supabase, authUser.studioId, 'marketing_advanced')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return { ok: false, error: 'Mass messaging requires the Studio plan or higher.' }
    }
    throw err
  }

  const parsed = MassBlastSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { clientIds, channel, body, subject } = parsed.data
  const { studioId } = authUser

  try {
    const supabase = await createClient()

    // Insert queued comm rows for each client (one per client)
    const rows = clientIds.map((clientId) => ({
      studio_id: studioId,
      client_id: clientId,
      channel,
      direction: 'outbound',
      subject: channel === 'email' ? (subject ?? '(no subject)') : null,
      body,
      status: 'queued',
      metadata: { blast: true } as Record<string, unknown>,
    }))

    const { data: insertedComms, error: insertError } = await supabase
      .from('client_communications')
      .insert(rows)
      .select('id')

    if (insertError || !insertedComms) {
      logger.error({ err: insertError, studioId }, 'massBlastAction: batch insert failed')
      return { ok: false, error: 'Failed to queue messages' }
    }

    // Enqueue single BullMQ job with all comm IDs
    const commIds = insertedComms.map((c) => c.id)
    await enqueueJob('send-mass-blast', { commIds, studioId, channel })

    revalidateMessages()
    return { ok: true, data: { queued: commIds.length } }
  } catch (err) {
    logger.error({ err }, 'massBlastAction: unexpected error')
    return { ok: false, error: 'Failed to send mass blast' }
  }
}

