/**
 * Job queue — typed enqueuer for BullMQ workers.
 *
 * This module ONLY enqueues. Workers (in workers/jobs/) process the jobs.
 * The web app never imports BullMQ directly — just this typed enqueuer.
 *
 * Falls back to a warning log when REDIS_URL is absent (local dev without Redis).
 * In production, REDIS_URL must be set or all background jobs silently drop.
 */
import 'server-only'
import { logger } from '@/lib/logger'

// ─── Job payload types ────────────────────────────────────────────────────────
// Each job name maps to a strongly-typed payload.
// Adding a new job: add entry here + handler in workers/jobs/

export interface JobPayloadMap {
  // Generic email dispatch — worker routes to template
  'send-email': {
    to: string
    template: string
    data: Record<string, unknown>
  }

  // AI design generation
  'process-ai-design': {
    requestId: string
    studioId: string
  }

  // Calendar sync
  'sync-calendar': {
    studioId: string
    artistId?: string
  }

  // Consent form PDF generation
  'generate-consent-pdf': {
    submission_id: string
    studio_id: string
  }

  // Tax form PDF generation
  'generate-tax-form-pdf': {
    form_id: string
    studio_id: string
  }

  // Tax form send to artist
  'send-tax-form': {
    form_id: string
    studio_id: string
    sent_by: string
  }

  // Marketing campaign dispatch
  'send-marketing-campaign': {
    campaignId: string
    studioId: string
    triggeredBy: string
  }

  // Payroll CSV export
  'payroll-csv-export': {
    preset: string
    from: string
    to: string
    studioId: string
  }

  // SMS send — worker reads comm row, calls Twilio, updates status + provider_message_id
  'send-sms': {
    commId: string     // client_communications.id
    studioId: string
  }

  // S24c — Consent-form auto-dispatch. Evaluator (lib/consent/evaluate-
  // auto-send-rules.ts) enqueues this per matching rule on booking
  // lifecycle events. Worker creates the consent_form_requests row + fires
  // the SMS/email with a one-time signing URL.
  'send-consent-form': {
    ruleId: string
    bookingId: string
    clientId: string
    studioId: string
  }

  // Messages v1 — delayed send. Fires at scheduled_for timestamp.
  // Worker reads the comm row by commId, dispatches via Twilio (SMS) or
  // Resend (email) based on channel, then updates status + sent_at.
  'send-scheduled-message': {
    commId: string
    studioId: string
  }

  // Sprint 6 — send deposit checkout link via email or SMS after Dodo checkout created.
  'send-deposit-link': {
    project_id: string
    client_id: string
    checkout_url: string
    amount_cents: number
    channel: 'email' | 'sms'
  }

  // Sprint 6 — fetch og:image / twitter:image for a project_references URL.
  'fetch-moodboard-thumbnail': {
    reference_id: string
  }
}

export type JobName = keyof JobPayloadMap

// ─── Queue configuration ──────────────────────────────────────────────────────
const QUEUE_NAME = 'inkos-jobs'

// ─── Lazy queue instance ──────────────────────────────────────────────────────
// Defined via interface to avoid importing BullMQ types at module level
interface QueueAddResult {
  id?: string | null
}
interface QueueInstance {
  add: (name: string, data: unknown, opts?: Record<string, unknown>) => Promise<QueueAddResult>
}

let _queue: QueueInstance | null = null
let _queueInitFailed = false

async function getQueue(): Promise<QueueInstance | null> {
  if (_queueInitFailed) return null
  if (_queue) return _queue

  const redisUrl = process.env.REDIS_URL
  if (!redisUrl) {
    return null
  }

  try {
    // Dynamic import so the web app bundle never includes BullMQ
    // The `as string` cast avoids static analysis bundling it
    const bullmq = await import('bullmq' as string) as { Queue: new (name: string, opts: unknown) => QueueInstance }
    _queue = new bullmq.Queue(QUEUE_NAME, {
      connection: {
        url: redisUrl,
        maxRetriesPerRequest: null,  // required for BullMQ ioredis compatibility
      },
      defaultJobOptions: {
        attempts: 3,
        backoff: { type: 'exponential', delay: 5_000 },
        removeOnComplete: 100,
        removeOnFail: 500,
      },
    })
    return _queue
  } catch (err) {
    _queueInitFailed = true
    logger.error({ err }, 'queue: failed to initialize BullMQ — jobs will be dropped')
    return null
  }
}

// ─── enqueueJob ───────────────────────────────────────────────────────────────

// ─── enqueueScheduledMessage ──────────────────────────────────────────────────

/**
 * Enqueue a scheduled-send message job with BullMQ delay.
 * @param commId - client_communications.id (status='queued', scheduled_for set)
 * @param studioId - for worker logging + routing context
 * @param sendAt - ISO timestamp when the message should fire
 */
export async function enqueueScheduledMessage(
  commId: string,
  studioId: string,
  sendAt: string,
): Promise<{ id: string }> {
  const delayMs = Math.max(0, new Date(sendAt).getTime() - Date.now())
  return enqueueJob('send-scheduled-message', { commId, studioId }, { delay: delayMs })
}

// ─── enqueueSendDepositLink ───────────────────────────────────────────────────

/**
 * Enqueue a send-deposit-link job.
 * Called from POST /api/projects/[id]/deposits/checkout when channel is email|sms.
 */
export async function enqueueSendDepositLink(params: {
  project_id: string
  client_id: string
  checkout_url: string
  amount_cents: number
  channel: 'email' | 'sms'
}): Promise<{ id: string }> {
  return enqueueJob('send-deposit-link', params)
}

// ─── enqueueFetchMoodboardThumbnail ──────────────────────────────────────────

/**
 * Enqueue a fetch-moodboard-thumbnail job.
 * Called after a URL reference is inserted into project_references.
 */
export async function enqueueFetchMoodboardThumbnail(
  reference_id: string
): Promise<{ id: string }> {
  return enqueueJob('fetch-moodboard-thumbnail', { reference_id })
}

export async function enqueueJob<T extends JobName>(
  jobName: T,
  payload: JobPayloadMap[T],
  opts?: { delay?: number; priority?: number },
): Promise<{ id: string }> {
  const queue = await getQueue()

  if (!queue) {
    logger.warn(
      { jobName },
      'queue: REDIS_URL not set or queue unavailable — job dropped (set REDIS_URL in .env.local for full functionality)',
    )
    return { id: `noop-${Date.now()}` }
  }

  try {
    const job = await queue.add(jobName, payload, {
      ...(opts?.delay !== undefined && { delay: opts.delay }),
      ...(opts?.priority !== undefined && { priority: opts.priority }),
    })
    logger.info({ jobName, jobId: job.id }, 'queue: job enqueued')
    return { id: job.id ?? `queued-${Date.now()}` }
  } catch (err) {
    logger.error({ err, jobName }, 'queue: failed to enqueue job')
    throw err
  }
}

