/**
 * send-mass-blast BullMQ worker.
 *
 * Consumes 'send-mass-blast' jobs from the inkos-jobs queue.
 * Job payload: { commIds: string[]; studioId: string; channel: 'sms' | 'email' }
 *
 * Processes in batches of 20 with 100ms delay between batches.
 * Respects Twilio rate limit (~100 SMS/s for A2P 10DLC, more conservatively 20/s).
 * Dispatches via:
 *   - channel='sms'   → Twilio (same as send-sms worker)
 *   - channel='email' → Resend (same as send-email worker)
 *
 * Updates each comm status to 'sent' or 'failed'.
 * Idempotent: skips comms already in a terminal state.
 */

import { Worker } from 'bullmq'
import { Twilio } from 'twilio'
import { Resend } from 'resend'
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'
import { workerEnv } from '../lib/env'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'send-mass-blast'
const BATCH_SIZE = 20
const BATCH_DELAY_MS = 100

interface SendMassBlastPayload {
  commIds: string[]
  studioId: string
  channel: 'sms' | 'email'
}

function isValidPayload(data: unknown): data is SendMassBlastPayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    Array.isArray((data as Record<string, unknown>)['commIds']) &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string' &&
    ((data as Record<string, unknown>)['channel'] === 'sms' ||
      (data as Record<string, unknown>)['channel'] === 'email')
  )
}

async function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

export function createSendMassBlastWorker(): Worker {
  return new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isValidPayload(job.data)) {
        logger.error({ jobData: job.data }, 'send-mass-blast: invalid payload')
        return
      }

      const { commIds, studioId, channel } = job.data

      logger.info({ count: commIds.length, studioId, channel }, 'send-mass-blast: starting')

      // Process in batches
      for (let i = 0; i < commIds.length; i += BATCH_SIZE) {
        const batch = commIds.slice(i, i + BATCH_SIZE)

        await Promise.all(
          batch.map((commId) => sendOne(commId, studioId, channel)),
        )

        // Delay between batches (except after the last one)
        if (i + BATCH_SIZE < commIds.length) {
          await sleep(BATCH_DELAY_MS)
        }
      }

      logger.info({ count: commIds.length, studioId }, 'send-mass-blast: completed')
    },
    {
      connection: {
        url: process.env['REDIS_URL'] ?? '',
        maxRetriesPerRequest: null,
      },
      concurrency: 2, // Low concurrency — each job already parallelizes within
    },
  )
}

async function sendOne(commId: string, studioId: string, channel: 'sms' | 'email'): Promise<void> {
  const { data: comm, error: fetchErr } = await supabase
    .from('client_communications')
    .select('id, client_id, body, subject, status')
    .eq('id', commId)
    .eq('studio_id', studioId)
    .single()

  if (fetchErr || !comm) {
    logger.warn({ commId }, 'send-mass-blast: comm not found — skipping')
    return
  }

  // Skip if already in terminal state
  if (['sent', 'delivered', 'failed'].includes(comm.status)) {
    return
  }

  if (channel === 'sms') {
    await sendViaSms(comm.id, comm.client_id as string, comm.body as string, studioId)
  } else {
    await sendViaEmail(
      comm.id,
      comm.client_id as string,
      comm.body as string,
      comm.subject as string | null,
      studioId,
    )
  }
}

async function sendViaSms(commId: string, clientId: string, body: string, studioId: string): Promise<void> {
  const accountSid = workerEnv.TWILIO_ACCOUNT_SID
  const authToken = workerEnv.TWILIO_AUTH_TOKEN
  const fromNumber = workerEnv.TWILIO_PHONE_NUMBER

  if (!accountSid || !authToken || !fromNumber) {
    await markFailed(commId, 'Twilio not configured')
    return
  }

  // Fetch client phone
  const { data: client } = await supabase
    .from('clients')
    .select('phone')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (!client?.phone) {
    await markFailed(commId, 'No phone number')
    return
  }

  try {
    const twilio = new Twilio(accountSid, authToken)
    const msg = await twilio.messages.create({ body, from: fromNumber, to: client.phone })
    await supabase
      .from('client_communications')
      .update({ status: 'sent', provider_message_id: msg.sid, sent_at: new Date().toISOString() })
      .eq('id', commId)
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : 'Twilio error'
    logger.error({ err, commId }, 'send-mass-blast: SMS send failed')
    await markFailed(commId, errMsg)
  }
}

async function sendViaEmail(
  commId: string,
  clientId: string,
  body: string,
  subject: string | null,
  studioId: string,
): Promise<void> {
  const apiKey = workerEnv.RESEND_API_KEY
  if (!apiKey) {
    await markFailed(commId, 'Resend not configured')
    return
  }

  const { data: client } = await supabase
    .from('clients')
    .select('email, first_name')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (!client?.email) {
    await markFailed(commId, 'No email address')
    return
  }

  const { data: studio } = await supabase
    .from('studios')
    .select('name, email_signature')
    .eq('id', studioId)
    .single()

  try {
    const resend = new Resend(apiKey)
    const result = await resend.emails.send({
      from: `${studio?.name ?? 'Your Studio'} <noreply@${process.env['RESEND_DOMAIN'] ?? 'inkos.studio'}>`,
      to: client.email,
      subject: subject ?? `Message from ${studio?.name ?? 'Your Studio'}`,
      text: body,
    })
    await supabase
      .from('client_communications')
      .update({
        status: 'sent',
        provider_message_id: result.data?.id ?? null,
        sent_at: new Date().toISOString(),
      })
      .eq('id', commId)
  } catch (err) {
    const errMsg = err instanceof Error ? err.message : 'Resend error'
    logger.error({ err, commId }, 'send-mass-blast: email send failed')
    await markFailed(commId, errMsg)
  }
}

async function markFailed(commId: string, error: string): Promise<void> {
  await supabase
    .from('client_communications')
    .update({ status: 'failed', error })
    .eq('id', commId)
}

