import { hasFeature } from '@/lib/billing/feature-gate'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { redirect } from 'next/navigation'

interface ProjectsLayoutProps {
  children: React.ReactNode
}

export default async function ProjectsLayout({ children }: ProjectsLayoutProps) {
  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  if (!hasFeature(activeStudio.plan, 'projects')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="pro"
          feature="Projects"
          description="Multi-session tattoo projects with shared deposit pools, photo progression, and moodboards. Upgrade to Pro to unlock."
        />
      </div>
    )
  }

  return <>{children}</>
}

