import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import Link from 'next/link'
import { createClient } from '@/lib/supabase/server'
import { GuestEngagementTabs } from '@/components/guest-artists/GuestEngagementTabs'
import { ChevronLeft } from 'lucide-react'

export const metadata: Metadata = {
  title: 'Guest Engagement — InkOS',
}

export default async function GuestEngagementPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (!member) redirect('/onboarding')

  const studioId = member.studio_id

  // DEV MODE: guest_artists plan gating removed — open to all plans.
  // Sidebar badge still indicates prod gating level.

  const isOwner = member.role === 'owner'

  return (
    <div className="p-6 space-y-6">
      <div>
        <Link
          href="/guest-artists"
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground mb-4"
        >
          <ChevronLeft className="h-3.5 w-3.5" />
          Guest Artists
        </Link>
      </div>
      <GuestEngagementTabs id={id} isOwner={isOwner} />
    </div>
  )
}

