'use client'

import Link from 'next/link'
import {
  LayoutDashboard,
  Inbox,
  CalendarDays,
  Users,
  Package,
  CreditCard,
  FolderKanban,
  BarChart2,
  Sparkles,
  Megaphone,
  FileText,
  Image,
  MapPin,
  MessageSquare,
  Briefcase,
  Zap,
  Star,
  X,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import { cn } from '@/lib/utils'
import {
  getPinnedItemKey,
  type PinnedItemPayload,
  type UserPinnedItem,
} from '@/lib/pinned-items/shared'

const ICON_MAP: Record<string, LucideIcon> = {
  LayoutDashboard,
  Inbox,
  CalendarDays,
  Users,
  Package,
  CreditCard,
  FolderKanban,
  BarChart2,
  Sparkles,
  Megaphone,
  FileText,
  Image,
  MapPin,
  MessageSquare,
  Briefcase,
  Zap,
  Star,
}

interface PinnedItemRowProps {
  item: UserPinnedItem
  pending: boolean
  onTogglePin: (payload: PinnedItemPayload) => void
}

// Render icon by name using a stable lookup — avoids creating components during render.
function PinnedIcon({ iconName }: { iconName: string | null }) {
  const IconComponent = ICON_MAP[iconName ?? ''] ?? Star
  return <IconComponent className="h-[17px] w-[17px] shrink-0 opacity-70" aria-hidden="true" />
}

function PinnedItemRow({ item, pending, onTogglePin }: PinnedItemRowProps) {
  function handleUnpin(e: React.MouseEvent) {
    e.preventDefault()
    e.stopPropagation()
    if (pending) return
    onTogglePin(item)
  }

  return (
    <SidebarMenuItem className="group/favorite relative">
      <SidebarMenuButton
        render={<Link href={item.href} prefetch />}
        className={cn(
          'h-8 gap-2 rounded-md px-2.5 text-[13px] font-medium transition-all duration-150',
          'text-sidebar-foreground/85 hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
        )}
        tooltip={item.label}
      >
        <PinnedIcon iconName={item.icon} />
        <span className="truncate">{item.label}</span>
      </SidebarMenuButton>
      <SidebarMenuAction
        type="button"
        showOnHover
        aria-label={`Remove ${item.label} from favorites`}
        aria-busy={pending || undefined}
        onClick={handleUnpin}
        className={cn(
          'right-1 top-1 z-10 h-6 w-6 cursor-pointer rounded-md md:after:block',
          'transition-[opacity,background-color,color,transform] duration-150',
          'text-sidebar-foreground/45 hover:scale-105 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground',
          pending && 'cursor-progress hover:scale-100',
        )}
      >
        <X className="h-3.5 w-3.5" aria-hidden="true" />
      </SidebarMenuAction>
    </SidebarMenuItem>
  )
}

interface SidebarFavoritesProps {
  pinnedItems: UserPinnedItem[]
  pendingPinKeys: ReadonlySet<string>
  onTogglePin: (payload: PinnedItemPayload) => void
}

export function SidebarFavorites({
  pinnedItems,
  pendingPinKeys,
  onTogglePin,
}: SidebarFavoritesProps) {
  if (pinnedItems.length === 0) return null

  return (
    <SidebarGroup className="px-0 pb-4 pt-0 group-data-[collapsible=icon]:hidden">
      <SidebarGroupLabel className="mb-1 px-2.5 text-[10px] font-bold uppercase tracking-[0.12em] text-stone-brand/70">
        Favorites
      </SidebarGroupLabel>
      <SidebarMenu className="gap-0.5">
        {pinnedItems.map((item) => (
          <PinnedItemRow
            key={item.id}
            item={item}
            pending={pendingPinKeys.has(getPinnedItemKey(item.kind, item.target))}
            onTogglePin={onTogglePin}
          />
        ))}
      </SidebarMenu>
    </SidebarGroup>
  )
}

