import { cn } from '@/lib/utils'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface PlanBadgeProps {
  plan: PlanTier
  /** Visual variant. `minimal` = text-only label (sidebar use). `pill` = bordered chip (settings, upgrade prompts). */
  variant?: 'minimal' | 'pill'
  className?: string
}

const PLAN_LABELS: Record<PlanTier, string> = {
  solo: 'Solo',
  studio: 'Studio',
  pro: 'Pro',
  enterprise: 'Ent',
}

// Minimal variant — no bg, no border, just a subtle uppercase tag. Sidebar default.
const PLAN_MINIMAL_STYLES: Record<PlanTier, string> = {
  solo: 'text-stone-brand/60',
  studio: 'text-stone-brand/70',
  pro: 'text-stone-brand/80',
  enterprise: 'text-foreground/80',
}

// Pill variant — full chip w/ bg + border. For upgrade CTAs, studio switcher, page hero.
const PLAN_PILL_STYLES: Record<PlanTier, string> = {
  solo: 'bg-muted text-muted-foreground',
  studio: 'bg-muted text-stone-brand border border-stone-brand/30',
  pro: 'bg-muted text-foreground border border-border/60',
  enterprise: 'bg-foreground text-background',
}

export function PlanBadge({ plan, variant = 'minimal', className }: PlanBadgeProps) {
  if (variant === 'minimal') {
    return (
      <span
        className={cn(
          'shrink-0 text-[9px] font-bold uppercase leading-none tracking-[0.1em]',
          PLAN_MINIMAL_STYLES[plan],
          className,
        )}
        aria-label={`Requires ${PLAN_LABELS[plan]} plan`}
      >
        {PLAN_LABELS[plan]}
      </span>
    )
  }

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-1.5 py-px',
        'text-[9px] font-bold uppercase tracking-wide leading-none',
        PLAN_PILL_STYLES[plan],
        className,
      )}
      aria-label={`Requires ${PLAN_LABELS[plan]} plan`}
    >
      {PLAN_LABELS[plan]}
    </span>
  )
}

