  pending,
  onTogglePin,
}: {
  item: PinnedItemPayload
  isPinned: boolean
  pending: boolean
  onTogglePin: ((payload: PinnedItemPayload) => void) | undefined
}) {
  function handlePin(e: React.MouseEvent) {
    e.preventDefault()
    e.stopPropagation()
    if (pending) return
    onTogglePin?.(item)
  }

  return (
    <SidebarMenuAction
      type="button"
      showOnHover={!isPinned}
      aria-label={isPinned ? `Remove ${item.label} from favorites` : `Add ${item.label} to favorites`}
      aria-pressed={isPinned}
      aria-busy={pending || undefined}
      onClick={handlePin}
      className={cn(
        'right-1.5 top-1.5 z-10 h-5 w-5 cursor-pointer rounded-sm md:after:block',
        'transition-[opacity,color,transform] duration-150',
        // Quieter pinned state — muted stone instead of Rust-filled. The plan
        // badge (if any) carries the strong visual weight, not the pin.
        isPinned
          ? 'text-stone-brand hover:scale-110 hover:text-foreground'
          : 'text-sidebar-foreground/40 hover:scale-110 hover:text-sidebar-foreground',
        pending && 'cursor-progress hover:scale-100',
      )}
    >
      <Star className="h-3 w-3" fill={isPinned ? 'currentColor' : 'none'} aria-hidden="true" />
    </SidebarMenuAction>
  )
}

export function SidebarNavGroup({
  group,
  plan,
  isFirst,
  dynamicBadges = {},
  pinnedItemKeys,
  pendingPinKeys,
  onTogglePin,
}: SidebarNavGroupProps) {
  const pathname = usePathname()

  return (
    <SidebarGroup className={cn('px-0', isFirst ? 'pt-0' : 'pt-4')}>
      {group.label !== null && (
        <SidebarGroupLabel className="mb-1 px-2.5 text-[10px] font-bold uppercase tracking-[0.12em] text-stone-brand/70 group-data-[collapsible=icon]:hidden">
          {group.label}
        </SidebarGroupLabel>
      )}
      <SidebarMenu className="gap-0.5">
        {group.items.map((item) => {
          const isActive =
            item.href === '/dashboard'
              ? pathname === item.href
              : pathname === item.href || pathname.startsWith(item.href + '/')

          // S18 fix — plan gating is badge-only (no redirect/block).
          // `isPlanLocked` drives the informational "STUDIO" / "PRO" pill so users
          // know a feature is above their plan, but clicking still navigates. Page-
          // level or contextual gates inside the feature (if any) handle upsell.
          const isPlanLocked =
            !!item.requiredPlan &&
            !hasFeature(plan, item.featureKey ?? item.requiredPlan)

          // Resolve dynamic badge count
          const dynamicCount = item.dynamicBadge !== undefined ? (dynamicBadges[item.dynamicBadge] ?? 0) : 0

          // Decide which badge to show. Plan badge takes priority over dynamic
          // count/dot/new badges so the sidebar doesn't render two badges side-by-
          // side on a gated item.
          const showPlanBadge = isPlanLocked && !!item.requiredPlan && item.requiredPlan !== 'solo'
          const showCountBadge = !showPlanBadge && item.badgeType === 'count' && dynamicCount > 0
          const showDotBadge = !showPlanBadge && item.badgeType === 'dot' && dynamicCount > 0
          const showNewBadge = !showPlanBadge && item.badgeType === 'new'

          // Resolve icon display name for pin storage
          const iconName = (item.icon as { displayName?: string }).displayName ?? item.icon.name ?? null
          const pinPayload: PinnedItemPayload = {
            kind: 'nav',
            target: item.href,
            label: item.label,
            href: item.href,
            icon: iconName,
          }
          const pinKey = getPinnedItemKey(pinPayload.kind, pinPayload.target)
          const isPinned = pinnedItemKeys?.has(pinKey) ?? false
          const pinPending = pendingPinKeys?.has(pinKey) ?? false

          function formatCount(n: number): string {
            if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
            return String(n)
          }

          return (
            <SidebarMenuItem key={item.href} className="group/item relative">
              <SidebarMenuButton
                render={<Link href={item.href} prefetch />}
                isActive={isActive}
                className={cn(
                  'relative h-8 gap-2 rounded-md px-2.5 text-[13px] font-medium transition-all duration-150',
                  'text-sidebar-foreground/85 hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
                  'data-[active=true]:bg-primary/10 data-[active=true]:text-primary data-[active=true]:font-semibold',
                  // Reserve right padding for pin star (32px) when pinned or hover-reveal
                  // happens, so badges don't sit flush against the pin.
                  'pr-9',
                )}
                tooltip={item.label}
              >
                <item.icon
                  className={cn(
                    '!h-[17px] !w-[17px] shrink-0 transition-colors',
                    isActive
                      ? 'text-primary'
                      : 'text-sidebar-foreground group-hover/item:text-sidebar-foreground',
                  )}
                  strokeWidth={2.25}
                  aria-hidden="true"
                />
                <span className="truncate group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>

                {/* Right-edge zone — single badge at a time, consistent vertical align.
                    Priority: plan > count > new > dot. ml-auto pushes to flex-end,
                    mr-1 leaves a 4px gap before the pin star lane. */}

                {/* Plan badge — minimal text-only (no bg/border) for quieter hierarchy */}
                {showPlanBadge && item.requiredPlan && (
                  <PlanBadge
                    plan={item.requiredPlan}
                    variant="minimal"
                    className="ml-auto group-data-[collapsible=icon]:hidden"
                  />
                )}

                {/* Count badge — slim pill, tabular numerals, muted bg */}
                {showCountBadge && (
                  <span
                    className={cn(
                      'ml-auto inline-flex h-[18px] min-w-[20px] items-center justify-center',
                      'rounded-full px-1.5 text-[10px] font-semibold tabular-nums leading-none',
                      'group-data-[collapsible=icon]:hidden',
                      isActive
                        ? 'bg-primary/15 text-primary'
                        : 'bg-muted text-muted-foreground',
                    )}
                    aria-label={`${dynamicCount} items`}
                  >
                    {formatCount(dynamicCount)}
                  </span>
                )}

                {/* Dot badge — 6px rust circle for alerts */}
                {showDotBadge && (
                  <span
                    className="ml-auto flex h-1.5 w-1.5 shrink-0 rounded-full bg-rust group-data-[collapsible=icon]:hidden"
                    aria-label="Alert"
                  />
                )}

                {/* NEW badge — minimal text-only Rust label (matches PlanBadge weight) */}
                {showNewBadge && (
                  <span
                    className="ml-auto shrink-0 text-[9px] font-bold uppercase leading-none tracking-[0.1em] text-rust group-data-[collapsible=icon]:hidden"
                  >
                    NEW
                  </span>
                )}
              </SidebarMenuButton>

              {/* Hover-reveal pin star. When right-edge badge exists, pin shifts
                  inward (right-10) to sit beside the badge with 4px gap. */}
              <NavItemPin
                item={pinPayload}
                isPinned={isPinned}
                pending={pinPending}
                onTogglePin={onTogglePin}
              />
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

