import { cn } from '@/lib/utils'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface PlanBadgeProps {
  plan: PlanTier
  /** Visual variant. `minimal` = compact inline chip (sidebar nav). `pill` = prominent bordered chip (studio switcher, upgrade CTAs). */
  variant?: 'minimal' | 'pill'
  className?: string
}

const PLAN_LABELS: Record<PlanTier, string> = {
  solo: 'Solo',
  studio: 'Studio',
  pro: 'Pro',
  enterprise: 'Ent',
}

// Minimal variant — tiny colored pill immediately after label.
// Each plan tier gets its own brand-safe tint. Hierarchy: Studio (stone) →
// Pro (rust-earned accent) → Enterprise (onyx solid).
const PLAN_MINIMAL_STYLES: Record<PlanTier, string> = {
  solo: 'bg-muted/60 text-muted-foreground',
  studio: 'bg-[color-mix(in_srgb,var(--color-stone)_14%,transparent)] text-stone-brand',
  pro: 'bg-[color-mix(in_srgb,var(--color-rust)_10%,transparent)] text-rust',
  enterprise: 'bg-foreground text-background',
}

// Pill variant — full chip w/ bg + border. StudioSwitcher, upgrade prompts.
const PLAN_PILL_STYLES: Record<PlanTier, string> = {
  solo: 'bg-muted text-muted-foreground',
  studio: 'bg-muted text-stone-brand border border-stone-brand/30',
  pro: 'bg-muted text-foreground border border-border/60',
  enterprise: 'bg-foreground text-background',
}

export function PlanBadge({ plan, variant = 'pill', className }: PlanBadgeProps) {
  if (variant === 'minimal') {
    return (
      <span
        className={cn(
          'inline-flex shrink-0 items-center rounded-[4px] px-1.5 py-0.5',
          'text-[9px] font-bold uppercase leading-none tracking-[0.1em]',
          PLAN_MINIMAL_STYLES[plan],
          className,
        )}
        aria-label={`Requires ${PLAN_LABELS[plan]} plan`}
      >
        {PLAN_LABELS[plan]}
      </span>
    )
  }

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-1.5 py-px',
        'text-[9px] font-bold uppercase tracking-wide leading-none',
        PLAN_PILL_STYLES[plan],
        className,
      )}
      aria-label={`Requires ${PLAN_LABELS[plan]} plan`}
    >
      {PLAN_LABELS[plan]}
    </span>
  )
}

